  TEXTS = {
    "\nAnd so, XXX became a witch.\n\nStrange creatures dwelled in the witch's house.\nShe enjoyed talking with them...\n\nBut they could not warm XXX's heart,\n\nbecause they lacked human hearts.\n\nOne day, XXX made him a request.\n\"I want a human friend.\"\n\nIn his black cat form, \"he\" assented.\nHowever..." => "\nVà cứ thế, XXX đã trở thành một phù thủy.\n\nCó rất nhiều sinh vật lạ trú ngự trong\ncăn nhà của phù thủy.\n\nCô rất thích thú khi nói chuyện với chúng...\n\nNhưng chúng vẫn chưa đủ để sưởi ấm con tim\ncủa XXX,\n\nvì chúng thiếu sự ấm áp của loài người.\n\nMột ngày, XXX đã đưa hắn ta một yêu cầu.\n\"Tôi muốn có một người bạn là loài người.\"\n\n\"Hắn ta\", bên dưới hình dạng của con mèo đen,\nđã chấp nhận yêu cầu.\n\n\\c[10]Tuy nhiên......",
    "\nI was sick,\nso no one played with me.\n\nMy father and my mother\ndidn't love me." => "\nTôi bị bệnh,\nNên không ai tới chơi với tôi cả.\n\nCha và mẹ tôi không yêu thương tôi.",
    "\nI wouldn't X her.\nBecause she would save me\nfrom my sickness.\n\nSo I made her my \"friend.\"" => "\nTôi không X cô ấy.\nBởi vì cô ấy có thể giúp tôi thoát khỏi căn bệnh này.\n\nNên tôi đã biến cô ấy trở thành \"bạn\" của tôi.",
    "\nLong ago, in a poor town,\nthere lived a sick girl named XXX.\n\nFrom birth, XXX's face and legs festered,\nso she kept them wrapped in bandages.\n\nXXX's father never looked at her,\nnor did he ever speak to her.\n\nEven so, XXX was happy.\nBecause at least XXX's mother loved her." => "\nRất lâu trước kia, tại một thị trấn nghèo,\ntừng tồn tại một cô bé bệnh tật mang tên XXX.\n\nTừ khi XXX được sinh ra, mặt và chân của\ncô bị mưng mủ, vì thế nên cô luôn phải\n\nquấn chúng lại bằng băng cứu thương.\n\nCha XXX chưa bao giờ để mắt tới cô ấy,\ncũng như nói chuyện với cô ấy.\n\nDù thế nhưng XXX vẫn hạnh phúc.\nVì ít nhất mẹ của XXX vẫn yêu thương cô ấy.",
    "\nUnlike charms cast on oneself, it is no easy task\nto cast spells involving two people.\n\nThis is because the target of the spell\nneeds to have sincere consent.\n\nThus, a bond of trust must be built\nfor spells of this type to succeed." => "\nKhông giống như những loại phép thuật tự\nniệm lên chính mình, để thực hiện những phép\n\nliên quan đến hai người đòi hỏi những\nđiều kiện rất khó khăn.\n\nĐó là bởi vì phải cần có sự đồng ý\nthành thật từ đáy lòng mới có thể\n\nhoàn thành mục tiêu của phép này.\n\nDo đó, cả hai cần phải có sự tin tưởng\nlẫn nhau mới có thể\n\nđưa loại phép thuật này tiến đến thành công.",
    "\nWhen I X my father and mother…\n\nA demon came along\nand ate the two of them.\n\nThe demon took me to this forest.\n\nIt thanked me for the meal\nand gave me this house.\n\nThen I became a witch.\n\nThe demon said…\n\n\"If you let me eat more people,\nI'll teach you a spell to cure your illness.\"" => "\nKhi tôi X cha và mẹ của tôi...\n\nMột con quỷ đã xuất hiện\nvà ăn cả hai người bọn họ.\n\nCon quỷ đó đã đưa tôi tới khu rừng này.\n\nNó cảm ơn tôi vì bữa ăn và cho tôi căn nhà này.\n\nTừ đó tôi đã trở thành phù thủy.\n\nCon quỷ còn nói thêm rằng...\n\"Nếu ta có thể ăn thêm được nhiều người nữa,\nta sẽ chỉ ngươi một phép có thể giúp ngươi\nchữa được căn bệnh ngươi đang mắc phải.\"",
    "\nWhen surrounded by her mother's scent,\nXXX could forget all her suffering.\n\nHowever, one day,\nXXX's mother stopped loving her.\n\nWhat was XXX gazing at?\n\nHer mother's pretty white shoes?\\.\nOr the glinting craft knife?\n\n...\\.That was a very cold night." => "\nKhi được bao bọc bởi sự quan tâm của mẹ,\nXXX dường như có thể quên hết\n\ntất cả mọi sự đau đớn trong cô.\n\nTuy nhiên, một ngày nọ,\nmẹ của XXX không còn yêu thương cô nữa.\n\nGiờ đây XXX đang chăm chú nhìn vào thứ gì?\n\nĐôi giày trắng lộng lẫy của mẹ cô ấy?\\.\nHay là một con dao rọc giấy lấp lánh?\n\n...\\.Hôm ấy là một đêm rất lạnh lẽo.",
    "\nXXX made him a request.\n\"I want a human friend.\"\n\nIn his black cat form, \"he\" assented.\nHowever...\n\nXXX didn't see it.\n\nShe didn't see the \\c[10]hideously evil\nsmile that crept up on \"his\" face.\\c[0]" => "\nXXX đã đưa hắn ta một yêu cầu.\n\"Tôi muốn có một người bạn là loài người.\"\n\n\"Hắn ta\", bên dưới hình dạng của con mèo đen,\nđã chấp nhận yêu cầu.\n\nTuy nhiên...\n\nXXX không hề nhìn thấy.\n\nCô không hề nhìn thấy \\c[10]nụ cười đầy hiểm ác\nđang hiện trên mặt của \"hắn ta\".\\c[0]",
    "\n\\.\\.I know she'll say yes.\n\n\nBecause \\.she's so kind.\n\nBecause \\.she's so trusting.\nViola's going to be so surprised\\.\\.\nwhen we trade bodies.\n\\.My body's \\.\\.falling apart.\\.\\.\nIt hurts all over.\n\\.\\.I've gotten used to it,\\.\\.\nbut she probably can't take it.\n\n\\.It might make her cry and scream.\n\n\\.\\.\\.So I'll give her medicine.\n\\.\\.M\\w[1]e\\w[1]d\\w[1]i\\w[1]c\\w[1]i\\w[1]n\\w[1]e\\w[1] \\w[1]t\\w[1]h\\w[1]a\\w[1]t\\w[1] \\w[1]w\\w[1]i\\w[1]l\\w[1]l\\w[1] \\w[1]b\\w[1]u\\w[1]r\\w[1]n \\w[1]h\\w[1]e\\w[1]r\\w[1] \\w[1]t\\w[1]h\\w[1]r\\w[1]o\\w[1]a\\w[1]t\\.\\.\nto make sure she stays quiet.\n\\.\\.After all, I don't want to hear\nmy own screaming.\n\\.\\.I know she'll drink it if I lie and say\\.\\.\nit'll stop the pain. \\.\\.\\.Heehee.\n\n\\.\\.\\.Then I'll escape from this room.\n\\.\\.I'll be able to feel a gentle breeze wash\nover me in the garden.\\! It'll be so wonderful.\n\n\\.\\.Ah, that's right.\n\\.\\.Before she gets here,\\.\\.\nI should gouge my eyes out.\\.\\.\n\nI'll cut off my legs, too.\\.\\.\n\\.\\.That way, Viola will be so overcome\nwith despair\\.\\. that she'll have to die.\n\n\\.\\.Ahhh... \\.\\.Viola.\n\n\\.My dear \"friend.\"\n\\.\\.So kind, \\.so charming, \\.so loved.\\.\\.\\.\nAnd with all that, \\.so foolish.\n\n\\.My dear \"friend.\"" => "\n\\.\\.Mình biết cô ấy sẽ nói đồng ý.\n\nBởi vì \\.cô ấy rất tốt bụng.\n\nVà \\.rất đáng tin cậy.\n\nViola đã rất ngạc nhiên\\.\\.\nkhi chúng tôi trao đổi thân xác với nhau.\n\n\\.Cơ thể của tôi \\.\\.như bị xé nát.\\.\\.\nCảm giác đau đớn không thể tả.\n\n\\.\\.Tôi đã quen với nó,\\.\\.\nnhưng cô ấy chắc chắn sẽ không chịu nổi nó.\n\n\\.Nó có thể làm cô ấy khóc và hét toáng lên.\n\n\\.\\.\\.Nên tôi đã đưa cho cô ấy thuốc của mình,\n\n\\.\\.\\c[2]Thuốc mà sẽ làm cổ họng bị thiêu\nhủy khi uống vào\\.\\.\n\n\\c[2]để chắc chắn rằng cô ấy sẽ\nluôn giữ yên lặng.\n\n\\.\\.Dù gì thì, mình cũng không muốn nghe thấy\ntiếng của mình khi hét toáng lên thế kia.\n\n\\.\\.\\c[2]Mình cam đoan cô ấy sẽ uống nó\nkhi mình nói dối rằng\\.\\.\n\n\\c[2]thứ thuốc đó sẽ chấm dứt cơn đau.\n\\.\\.\\.Heehee....\n\n\\.\\.\\.Và mình sẽ có thể cảm nhận được\ncơn gió lạnh luồng qua mình ở khu vườn.\\!\n\nNó chắc chắn sẽ rất tuyệt.\n\n\\.\\.\\.Ah, phải rồi.\n\n\\.\\.Trước khi cô ấy đến đây,\\.\\.\nMình phải nên móc đôi mắt này ra.\\.\\.\n\nMình cũng sẽ cắt đi đôi chân này.\\.\\.\n\n\\.\\.Bằng cách này, Viola sẽ trở nên tuyệt vọng\\.\\.\nvà cô ấy sẽ chết.\n\n\\.\\.Ahhh... \\.\\.Viola.\n\n\\.\"Người bạn\" yêu quý của tôi.\n\n\\.\\.Thật tốt, \\.thật quyến rũ, \\.thật đáng yêu.\\.\\.\\.\nVà sau tất cả,\\. cô thật ngu ngốc.\n\n\\.\"Người bạn\" yêu quý của tôi.",
    "\n\\CL \\c[10]FATHER IGNORED ME" => "\n\\CL \\c[10]CHA THÌ KHÔNG QUAN TÂM TÔI\nNHƯ THỂ TÔI KHÔNG TỒN TẠI",
