    "  And she met \"him,\" in the form of a black cat." => "\"Hắn ta\", dưới hình dạng của một con mèo đen.",
    "  And so, XXX became a witch.\n\nStrange creatures dwelled in the witch's house.\nShe enjoyed talking with them...\n\nBut they could not warm XXX's heart,\n\nbecause they lacked human hearts.\n\nOne day, XXX made him a request.\n\"I want a human friend.\"\n\nIn his black cat form, \"he\" assented.\nHowever..." => "\nVà cứ thế, XXX đã trở thành một phù thủy.\n\nCó rất nhiều sinh vật lạ trú ngự trong\ncăn nhà của phù thủy.\n\nCô rất thích thú khi nói chuyện với chúng...\n\nNhưng chúng vẫn chưa đủ để sưởi ấm con tim\ncủa XXX,\n\nvì chúng thiếu sự ấm áp của loài người.\n\nMột ngày, XXX đã đưa hắn ta một yêu cầu.\n\"Tôi muốn có một người bạn là loài người.\"\n\n\"Hắn ta\", bên dưới hình dạng của con mèo đen,\nđã chấp nhận yêu cầu.\n\n\\c[10]Tuy nhiên......",
    "  Are you hurt anywhere?\"" => "Con có bị đau ở đâu không?\"",
    "  Are you that worried about your father?\"" => "Cô lo lắng cho cha cô đến thế sao?\"",
    "  Artificial flowers adorn the desk." => "Hoa nhân tạo trang trí trên bàn.",
    "  Artificial roses adorn the desk." => "Hoa hồng nhân tạo trang trí trên bàn.",
    "  Artificial roses decorate the wall." => "Hoa hồng nhân tạo trang trí trên tường.",
    "  Artificial roses." => "Hoa hồng nhân tạo.",
    "  Bandages and antiseptic solution." => "Băng và lọ dung dịch khử.",
    "  Beautiful Flower" => "\\>Bông hoa xinh đẹp\\<",
    "  Because \"she\" showed up, it looks like.\"" => "Vì có vẻ như \"cô ta\" đã xuất hiện rồi.\"",
    "  Being a powerless human hasn't been so bad." => "Với ta thì cơ thể người phàm cũng không đến nỗi tệ.",
    "  Better not with the fire still burning." => "Tốt hơn là không có lửa vẫn cháy.",
    "  Black Cat" => "Mèo Đen",
    "  Black Cat\n\"And it seems the magic of the house\nhas gone back to her.\"\nBlack Cat\n\"Which means the magic's gonna go poof, right?\nIf I stay here, I might get gobbled up with it.\"" => "\\>Hắc Miêu\\<\n\"Và có vẻ như phép thuật trong căn nhà đang quay\nlại với con bé.\"\n\\>Hắc Miêu\\<\n\"Nghĩa là tất cả phép thuật ở đây sẽ biến mất hết,\nđúng không?\nNếu còn ở lại đây, tôi sẽ bị cuốn vào mất.\"",
    "  Black Cat\n\"I kinda like this place.\\!\nYou?\"" => "\\>Hắc Miêu\\<\n\"Tôi khá thích nơi này, còn cô?\"",
    "  Black Cat\n\"Might as well, if you can't leave.\"" => "\\>Hắc Miêu\\<\n\"Có lẽ không còn cách nào khác, nếu cô không\nthể ra khỏi đây\"",
    "  Black Cat\n\"Yo.\"\nBlack Cat\n\"Yeah, I'm here too. All in the job.\"" => "\\>Hắc Miêu\\<\n\"Chào.\"\n\\>Hắc Miêu\\<\n\"Yeah, ta cũng ở đây mà.\nVì công việc thôi\"",
