    "  It does no harm." => "Nó vô hại.",
    "  It doesn't make much of a sound." => "Nó không gây nhiều tiếng động cho lắm.",
    "  It kept me from going outside." => "Nó khiến tôi không thể bước ra ngoài.",
    "  It kept people from loving me." => "Vì nó mà mọi người không yêu thương tôi.",
    "  It makes a pleasing sound." => "Nó phát ra âm thanh êm tai.",
    "  It rammed the door." => "Nó đâm vào cửa.",
