    "  The wall's covered in\nsomething red and sticky." => "Bức tường được phủ lên một lớp gì đó đỏ và dính.",
    "  The water runs red." => "Nước trở nên đỏ rực.",
    "  The way is blocked by a small patch of roses." => "Lối đi bị chặn bởi một bụi hoa hồng nhỏ.",
    "  The way is blocked by a startlingly huge patch of roses." => "Lối đi bị chặn bởi bụi hoa hồng khổng lồ đáng sợ.",
    "  The way is cleared." => "Lối đi đã được dọn sạch.",
    "  The way out is blocked up by roses, huh?\"" => "Có vẻ lối đi đã bị chặn bởi hoa hồng à?\"",
    "  The white cat is holding some thick rope." => "Con mèo trắng đang giữ một sợi dây thừng dày.",
    "  The white flowers ... most beautiful ... garden." => "Bông hoa trắng .... đẹp nhất ..... khu vườn ....",
    "  The white flowers are most beautiful of the garden." => "Những bông hoa trắng đẹp nhất khu vườn.",
    "  The window is shut fast." => "Cửa sổ đóng chặt.",
    "  The window is shut fast.\\." => "Cửa sổ đóng chặt.\\.",
    "  The witch's house devours humans\nand offers their souls up to a demon." => "Ngôi nhà của phù thủy sẽ ăn thịt con người và linh\nhồn của những kẻ xấu số đó sẽ thành bữa ăn cho\nác quỷ.",
    "  The witch's house devours humans." => "Ngôi nhà phù thủy nuốt chửng con người.",
    "  The witch's house has a will of its own." => "Ngôi nhà phù thủy có ý chí của riêng nó.",
    "  The witch's house has a will of its own.\nIts residents are the remnants of souls\nfed to the demon, and thus lack any will." => "Ngôi nhà của phù thủy có một ý chí riêng của\nriêng nó.\nNó là tàn dư linh hồn của những kẻ đã trở thành\nbữa ăn của ác quỷ.\nNhưng vì đã bị ăn nên nó thiếu mất một phần\ný chí để tự vận hành được.",
    "  The witch's house is magic," => "Ngôi nhà phù thủy là ma thuật,",
    "  The witch's house is magic,\ngranted to a witch by a demon." => "Ngôi nhà của phù thủy như là một phép thuật,\nđược ác quỷ trao cho những kẻ đã lập khế ước\nvới hắn.",
    "  The woman is gone from it." => "Người phụ nữ đã biến mất khỏi đó.",
    "  The woman spit something out." => "Người phụ nữ đưa thứ gì đó ra.\n",
    "  The yellow flower lies in cut-up pieces." => "Bông hoa vàng nằm đứt đoạn từng khúc.",
    "  The yellow flower's been sliced to bits." => "Những bông hoa vàng bị sắc thành từng mảnh nhỏ.",
    "  The yellow flowers are having a fun chat." => "Những bông hoa vàng đang có cuộc trò chuyện vui vẻ.",
    "  The yellow flowers are having pleasant conversation." => "Những bông hoa vàng đang trò chuyện rôm rả.",
    "  Their bodies were found to have stab wounds," => "Thi thể của họ có nhiều vết đâm,",
    "  Their eye colors depend on their hair color.\\!" => "\\>  Màu mắt của mỗi người phụ thuộc vào màu tóc của họ.",
    "  Their eye colors depend on their hair color.\\hold\\^" => "Màu mắt của họ phụ thuộc vào màu tóc.\\hold\\^",
    "  Their souls are offered to a demon." => "Linh hồn họ bị hiến tế cho ác quỷ.",
    "  Then I fed them all to the house." => "Và tôi đem hết tất cả chúng làm thức ăn cho ngôi nhà.",
    "  There are bloody scissors on the workbench." => "Cây kéo bị dính máu.",
    "  There are cracked bottles up on the shelf." => "Một chai lọ bị nứt được đặt trên kệ.",
    "  There are empty bottles up on the shelf." => "Có những chiếc chai rỗng trên kệ.",
    "  There are some notes on the table." => "Có vài mẩu giấy ghi chú trên bàn.",
    "  There was once a soldier.\\!" => "Ngày xưa từng có một người lính.\\!",
    "  There was once a soldier.\\!\nUnbeknownst to him, his country had\nalready perished... and so had he.\nEven in death, the soldier patrolled.\nStarting in the \\c[14]center\\c[0] of the castle ruins,\nhe looked \\c[9]forward\\c[0], \\c[9]right\\c[0], \\c[9]left\\c[0], \\c[9]forward\\c[0], \\c[9]right\\c[0], \\c[9]left\\c[0]..." => "Ngày xưa tùng có một người lính.\nMột người lính vô danh không ai biết tới và\ncũng không ai biết nơi anh ấy sinh ra....\nMột ngày nọ anh lính ấy đã bị địch tấn công.....\nvà anh ta đã tử trận.\nThậm chí sau khi chết, người lính vẫn thực hiện\nnhiệm vụ tuần tra của mình.\nBắt đầu từ \\c[14]trung tâm\\c[0] của lâu đài,\nAnh ta nhìn về \\c[9]phía trước\\c[0], \\c[9]phải\\c[0], \\c[9]trái\\c[0], \\c[9]phía trước\\c[0],\n\\c[9]phải\\c[0], \\c[9]trái\\c[0].....",
    "  There's a 12 card with a queen on it," => "Có 12 thẻ bài với nữ hoàng trên đó,",
    "  There's a big dragging mark on the floor." => "Một vật gì đó khá lớn đã bị kéo lê\nvà để lại vết kéo trên sàn nhà.",
    "  There's a blue-winged butterfly model in the case.\\!" => "Có mô hình bướm cánh xanh trong hộp kính.\\!",
    "  There's a book titled \"Book of Death.\"" => "Tên cuốn sách \"Cuốn sách tử thần\".",
    "  There's a giant snake." => "Một con rắn to lớn.",
    "  There's a hole and an iron ladder going down." => "Có một cầu thang sắt dẫn xuống phía dưới.",
    "  There's a hole just big enough to crawl in.\\!" => "Có một cái lỗ vừa đủ để chui vào.\\!",
    "  There's a hole.\\!" => "Có một cái lỗ.\\!",
    "  There's a little bit of room left." => "Vẫn còn một khoảng trống nhỏ.",
    "  There's a pair of scissors on the workbench.\\!" => "Một cặp kéo nằm ở trên bàn làm việc.\\|",
    "  There's a piece of cake.\\!" => "Có một miếng bánh ngọt.\\!",
    "  There's a piece of rope in the barrel.\\!" => "Có một đoạn dây thừng trong thùng.\\!",
    "  There's a piece of shortcake on the table.\\!" => "Có một miếng bánh dâu trên bàn.\\!",
    "  There's a rose on the table.\\!" => "Có một bông hoa hồng trên bàn.\\!",
    "  There's a scrap of paper.\\!" => "Có một mẩu giấy vụn.\\!",
    "  There's a skull in one of the drawers.\\!" => "Có một hộp sọ trong ngăn kéo.\\!",
    "  There's a skull inside the barrel." => "Có một hộp sọ trong thùng.",
    "  There's a skull on a cobwebbed shelf." => "Có một hộp sọ trên kệ đầy mạng nhện.",
    "  There's a skull on the floor.\\!" => "Có một hộp sọ trên sàn.\\!",
    "  There's a small hole in the wall." => "Có một lỗ nhỏ bên trong bức tường.",
    "  There's a small skull on the chair.\\!" => "Có một hộp sọ nhỏ trên ghế.\\!",
    "  There's a small wristwatch.\\!" => "Có một chiếc đồng hồ đeo tay nhỏ.\\!",
    "  There's a switch on the frame.\\!" => "Có một công tắc trên khung.\\!",
    "  There's a viewing window the size of your palm." => "Có ô cửa sổ quan sát nhỏ bằng lòng bàn tay.",
    "  There's a wristwatch under the table.\\!" => "Có một chiếc đồng hồ đeo tay dưới gầm bàn.\\!",
    "  There's an iron ladder in the fireplace." => "Có một chiếc thang sắt trong lò sưởi.",
    "  There's an old legend that says a witch lives in" => "Có truyền thuyết kể rằng một phù thủy sống trong",
    "  There's chocolate cake on the table." => "Có bánh chocolate trên bàn.",
    "  There's chopsticks in the skeleton's ribs.\\!" => "Có đôi đũa cắm trong sườn bộ xương.\\!",
    "  There's no path here anymore." => "Không còn lối đi nào ở đây nữa.",
    "  There's nothing else." => "Không còn gì khác.",
    "  There's nothing here." => "Không có gì ở đây.",
    "  There's nothing in the glass case." => "Không có gì trong tủ kính.",
    "  There's nothing inside." => "Không có gì bên trong.",
    "  There's nothing left underneath." => "Chẳng còn gì bên dưới nữa.",
    "  There's nothing on the music rest.\\!" => "Không có gì trên giá để bản nhạc.\\!",
    "  There's nothing under the table." => "Không có gì ở bên dưới ngăn bàn.",
    "  There's nothing underneath." => "Không có gì ở bên dưới.",
    "  There's nowhere to use a turnkey." => "Không có chỗ nào để tra chìa khóa vặn vào.",
    "  There's one Jack, one Queen, and one King." => "Có một quân J, một quân Q, và một quân K.",
    "  There's only empty dishes and cups." => "Chỉ có bát đĩa và cốc chén trống không.",
    "  There's some fur left on the ground." => "Có chút lông thú vương trên sàn.",
    "  There's some fur left on the stump." => "Có một ít lông thú bên trái gốc cây.",
    "  There's someone invisible there.\\!" => "Có ai đó vô hình ở đằng kia.\\!",
    "  There's something in one of the drawers.\\!" => "Có thứ gì đó trong ngăn kéo.\\!",
    "  There's strawberry shortcake" => "Có bánh ngọt dâu tây",
    "  There's teddy bear limbs on the ground.\\!" => "Có tay chân gấu bông trên sàn.\\!",
    "  These are their characteristics." => "Đây là những đặc điểm của họ.",
    "  They don't seem useful." => "Chúng có vẻ không có ích gì.",
    "  They push your wrist onto the cutting board." => "Họ đè tay bạn lên một cái thớt.",
    "  They spit at you." => "Hắn nhổ nước bọt vào người bạn.",
    "  They were the words I was waiting to hear," => "Đó là những từ mà tôi đã phải chờ để được nghe,",
    "  They're chained to the bench." => "Chúng đã bị xích chặt vào bàn .",
    "  This body hurts much less.\"" => "Cơ thể này đỡ đau hơn nhiều.\"",
    "  This chair has toppled over." => "Chiếc ghế này đã bị lật nhào.",
    "  This grass is wet from rain." => "Đám cỏ này ướt sũng vì mưa.",
    "  This is because the target of the spell" => "Đó là vì đối tượng của bùa chú",
    "  This setting cannot be changed mid-game." => "Bạn không thể thay đổi cấp độ khi đang chơi.",
    "  This skeleton had chopsticks stuck in him." => "Đôi đũa đã dính vào bộ xương.",
    "  Thoroughly used." => "Được dùng rất nhiều lần.",
    "  Thus, a bond of trust must be built" => "Do đó, phải xây dựng một mối liên kết tin tưởng",
    "  Thuốc diệt hoa hồng của phù thủy. Có mùi ngọt ngào." => "Thuốc diệt hoa hồng của phù thủy. Có mùi ngọt ngào.",
    "  Thân Gấu Bông" => "Thân Gấu Bông",
    "  Time marches on." => "Thời gian đang trôi đi.",
    "  Time marches on.\\!" => "Thời gian trôi đi.\\!",
    "  To XXX, \"despair\" was the scent" => "Với XXX, \"tuyệt vong\" chỉ là mùi hương",
    "  To XXX, \"friends\" were humans" => "Với XXX, \"bạn bè\" chỉ là những kẻ",
    "  Too dangerous.\"" => "Nơi này nguy hiểm lắm.\"",
    "  Tore the note off." => "Đã xé tờ giấy.",
    "  Toss in jade pipe" => "Ném tẩu thuốc vào trong",
    "  Tossed the jade pipe through the bars." => "Tẩu thuốc đã bị ném qua song sắt.",
    "  Touch" => "Chạm vào nó",
    "  Transferred the flame to the green candle." => "Đã chuyển ngọn lửa sang cây nến màu xanh lá.",
    "  Tôi trông cũng khá giống một con mèo đó chứ.\"" => "Và ta khá thích cơ thể màu đen này.\"",
    "  Tẩu Thuốc Ngọc Bích" => "Tẩu Thuốc Ngọc Bích",
    "  Unlike charms cast on oneself, it is no easy task" => "Không giống như bùa chú tác động lên bản thân,",
    "  Unlike charms cast on oneself, it is no easy task\nto cast spells involving two people.\n\nThis is because the target of the spell\nneeds to have sincere consent.\n\nThus, a bond of trust must be built\nfor spells of this type to succeed." => "\nKhông giống như những loại phép thuật tự\nniệm lên chính mình, để thực hiện những phép\n\nliên quan đến hai người đòi hỏi những\nđiều kiện rất khó khăn.\n\nĐó là bởi vì phải cần có sự đồng ý\nthành thật từ đáy lòng mới có thể\n\nhoàn thành mục tiêu của phép này.\n\nDo đó, cả hai cần phải có sự tin tưởng\nlẫn nhau mới có thể\n\nđưa loại phép thuật này tiến đến thành công.",
    "  Uproot" => "Nhổ lên",
    "  Use key" => "sử dụng chìa khóa",
    "  Used a nearby cloth to pull off the cover." => "Dùng mảnh vải để mở nắp ra.",
    "  Using items" => "Sử dụng vật phẩm",
    "  Viola" => "Viola",
    "  Viola\n\"Hm? \"\\w[2]G\\w[2]i\\w[2]v\\w[2]e\\w[2] i\\w[2]t\\w[2] b\\w[2]a\\w[2]c\\w[2]k\\w[2]?\\w[2]\"\\! No way.\\!\nI don't feel any pain in this body.\"" => "Viola\n\"Hm? \"Trả lại sao?\"\\! Không đời nào.\\!\"\nViola\n\"Tớ không cảm thấy cơn đau nào khi\nở trong cơ thể này.\"",
    "  Viola\n\"I was surprised you managed to trap\nme in there... \\.\\....\\.but, to no avail.\"\nViola\n\"After all, \\.\\.it's my house.\\!\nWhy would it ever kill me?\"\nViola\n\"The house guided me the entire way\\.\\.\nto ensure that I would escape.\"" => "Viola\n\"Tớ đã khá ngạc nhiên khi cậu có thể đặt\nbẫy tớ trong đó đấy...\\.\\....\\.\"\nViola\n\"Nhưng tất cả chỉ là vô ích thôi.\"\nViola\n\"Sau cùng, \\.\\.đấy là nhà của tớ mà.\\!\nLàm sao nó có thể giết được tớ chứ?\"\nViola\n\"Vì chính ngôi nhà này đã dẫn đường cho\ntớ.\\.\\. Để đảm bảo tớ có thể thoát khỏi\nđây.\"",
    "  Viola\n\"It'll be just fine.\n\\! I'll make sure his daughter,\n\\.\\w[2]V\\w[2]i\\w[2]o\\w[2]l\\w[2]a\\w[2], g\\w[2]i\\w[2]v\\w[2]e\\w[2]s\\w[2] h\\w[2]i\\w[2]m\\w[2] h\\w[2]e\\w[2]r\\w[2] s\\w[2]h\\w[2]a\\w[2]r\\w[2]e\\w[2] o\\w[2]f\\w[2] l\\w[2]o\\w[2]v\\w[2]e\\w[2].\"\nViola\n\"And I'll \\.\\w[4]t\\w[4]a\\w[4]k\\w[4]e\\w[4] \\w[4]her share of love, too.\"" => "Viola\n\"Mọi thứ sẽ ổn cả thôi.\\!\nTớ sẽ đảm bảo rằng con gái của ông ấy,\nsẽ chia sẻ tình yêu của mình với ông ấy.\"\nViola\n\"Và tớ cũng sẽ lấy đi thứ tình yêu\nđấy từ cậu.\"",
    "  Viola\n\"Oh, I know all about you and your\nfather, Viola.\\! A close family of two.\"" => "Viola\n\"Oh, tớ biết tất cả mọi thứ về cậu lẫn\ncha cậu, Viola à.\\!\nMột gia đình đầm ấm chỉ có hai cha con.\"",
    "  Viola\n\"So then,\nI suppose you're worried about\\.\nwhat'll happen when you're gone?\"" => "Viola\n\"Thế nên, tớ cho là cậu đang lo lắng rằng\\.\nchuyện gì sẽ xảy ra khi cậu chết đi?\"",
    "  Viola\n\"You felt so sorry for me.\\!\nI couldn't even move from my bed.\"" => "Viola\n\"Cậu đã cảm thấy thương tiếc cho tớ.\\!\nTớ thậm chí còn không thể bước ra\nkhỏi giường.\"",
    "  Viola\n\"\\fs[27]Ah, \\.\\.maybe you're...\\!\n...too worried about your father to die?\\fs[29]\"" => "Viola\n\"\\fs[27]Ah,\\.\\. có phải cậu...\\!\n... Đang rất lo lắng cho cha cậu nên vẫn\nchưa thể chết?\\fs[29]\"",
    "  Viola\n\"\\fs[27]How long are you going to chase me?\\!\nYou know you're almost dead.\\fs[29]\"" => "Viola\n\"\\fs[27]Cậu còn tính đuổi theo tớ\ntới khi nào?\\!\\fs[29]\nViola\n\"\\fs[27]Cậu biết cậu sắp chết đến nơi\nrồi mà.\\fs[29]\"",
    "  Viola\n\"\\fs[28]Those memories stayed in your body.\\!\nHe's a kind man. \\! A hunter, isn't he?\\fs[29]\"\nViola\n\"And he even sent you that letter.\nWhat a good father.\"" => "Viola\n\"\\fs[28]Kí ức của cậu vẫn bên trong cơ\nthể này mà.\\!\nÔng ấy là một người tốt bụng. \\!\\fs[29]\nViola\n\"\\fs[28]Một thợ săn, đúng không nhỉ?\\fs[29]\"\nViola\n\"Và ông ấy thậm chí còn gửi cho cậu lá\nthư đó.\nĐúng là một người cha tuyệt vời.\"",
    "  Viola would sit in this and talk with me." => "Viola từng ngồi trên chiếc ghế này trò chuyện cùng tôi.",
    "  Viola's Dad" => "Cha Viola",
    "  Wash shoes" => "Rửa giày",
    "  Washing away the blood, the shoes become clear." => "Rửa sạch vết máu, đôi giày trở nên trong suốt.",
    "  We know the following about" => "Chúng biết điều này nhờ những quan sát những",
    "  Wear shoes" => "Mang giày vào",
    "  Well, go have fun.\"" => "Chà, chúc cô đi vui vẻ nhá.\"",
    "  What a good father.\"" => "Đúng là một người cha tuyệt vời.\"",
    "  What she found" => "Và những gì cô tìm được",
    "  What she obtained" => "Nhưng những gì cô thu được",
    "  When I X my father and mother…\n\nA demon came along\nand ate the two of them.\n\nThe demon took me to this forest.\n\nIt thanked me for the meal\nand gave me this house.\n\nThen I became a witch.\n\nThe demon said…\n\n\"If you let me eat more people,\nI'll teach you a spell to cure your illness.\"" => "\nKhi tôi X cha và mẹ của tôi...\n\nMột con quỷ đã xuất hiện\nvà ăn cả hai người bọn họ.\n\nCon quỷ đó đã đưa tôi tới khu rừng này.\n\nNó cảm ơn tôi vì bữa ăn và cho tôi căn nhà này.\n\nTừ đó tôi đã trở thành phù thủy.\n\nCon quỷ còn nói thêm rằng...\n\"Nếu ta có thể ăn thêm được nhiều người nữa,\nta sẽ chỉ ngươi một phép có thể giúp ngươi\nchữa được căn bệnh ngươi đang mắc phải.\"",
    "  When I heard those words," => "Khi tôi nghe thấy những từ đó,",
    "  When surrounded by her mother's scent,\nXXX could forget all her suffering.\n\nHowever, one day,\nXXX's mother stopped loving her.\n\nWhat was XXX gazing at?\n\nHer mother's pretty white shoes?\\.\nOr the glinting craft knife?\n\n...\\.That was a very cold night." => "\nKhi được bao bọc bởi sự quan tâm của mẹ,\nXXX dường như có thể quên hết\n\ntất cả mọi sự đau đớn trong cô.\n\nTuy nhiên, một ngày nọ,\nmẹ của XXX không còn yêu thương cô nữa.\n\nGiờ đây XXX đang chăm chú nhìn vào thứ gì?\n\nĐôi giày trắng lộng lẫy của mẹ cô ấy?\\.\nHay là một con dao rọc giấy lấp lánh?\n\n...\\.Hôm ấy là một đêm rất lạnh lẽo.",
    "  When the man returned, \\!he saw the dog on guard.\\!" => "Khi phú ông trở lại, \\!ông thấy chú chó vẫn canh gác.\\!",
    "  When the water touches the petals," => "Khi nước chạm vào những cánh hoa,",
    "  When the witch's flowers wilt, the witch dies." => "tan biến.",
    "  When touched by rain, oddly, their petals glow." => "Khi gặp mưa, kỳ lạ thay, cánh hoa phát sáng.",
    "  Where?\\!" => "Ở đâu?\\!",
    "  Wherever" => "Đâu cũng được",
    "  White flowers" => "Bông hoa trắng",
    "  White petals are scattered on the ground.\\!" => "Cánh hoa trắng rơi vãi trên sàn.\\!",
    "  Why not try escaping a different way?\"" => "Sao cô không không thử cách khác đi?\"",
    "  Why should I \\.have to give it back?\"" => "Tại sao tớ phải \\.trả lại cho cậu chứ?\"",
    "  Why would it ever kill me?\"" => "Làm sao nó có thể giết tao được chứ?\"",
    "  Wine bottles are lined up on the shelf." => "Những chai rượu xếp thành hàng trên kệ.",
    "  Wine bottles line the shelf." => "Những chai rượu vang được xếp trên kệ.",
    "  Witches offer souls to demons." => "Những Phù thủy cung cấp linh hồn cho Ác quỷ.",
    "  With a scream, the beautiful flower expires." => "Cùng với tiếng hét lớn, bông hoa\nxinh đẹp đã bị tàn lụi.",
    "  With a strange shriek, the beautiful flower expires." => "Kèm theo tiếng thét kỳ quái, bông hoa xinh đẹp lụi tàn.",
    "  Withdraw" => "Đầu hàng",
    "  Woman Statue" => "\\>Bức tượng người phụ nữ\\<",
    "  Woman With Parasol" => "Người phụ nữ mang ô",
    "  Woman in Painting" => "\\>Người phụ nữ trong tranh\\<",
