    "  \\CL \\w[1]C\\w[1]O\\w[1]M\\w[1]E\\w[1] \\w[1]T\\w[1]O\\w[1] \\w[1]M\\w[1]Y\\w[1] \\w[1]R\\w[1]O\\w[1]O\\w[1]M\\w[1]" => "\\CL \\w[1]Đ\\w[1]Ế\\w[1]N\\w[1] \\w[1]P\\w[1]H\\w[1]Ò\\w[1]N\\w[1]G\\w[1] \\w[1]C\\w[1]Ủ\\w[1]A\\w[1] \\w[1]T\\w[1]A\\w[1]",
