    "  and use an item from the menu." => "và sử dụng vật phẩm từ menu.",
    "  and went home to check on his mother." => "rồi về nhà thăm mẹ già.",
    "  and what did you do? You stole from it!\"\\.\\." => "vậy mà mày lại dám ăn cắp!\"\\.\\.",
    "  are both proper ways to X.\"" => "đều là những cách có thể X.\"",
    "  are stuck to the table." => "dính chặt lên bàn.",
    "  as the piano plays itself." => "như thể chiếc piano đang tự động chơi.",
    "  as the reason she was not loved." => "mà khiến cho mọi người không yêu cô.",
    "  away from the forest. Hope to see you home soon." => "khu rừng ra nhé. Mong sớm gặp lại con ở nhà.",
    "  before the building was set aflame." => "trước khi tòa nhà bị phóng hỏa.",
    "  broken cookware. Nothing seems useful." => "bỉ hỏng. Chúng có vẻ không hữu dụng.",
    "  but don't go too deep into the forest." => "nhưng đừng vào sâu trong rừng.",
    "  but he noticed neither of these things." => "nhưng anh không hề hay biết điều đó.",
    "  but there came a passing hunter and his dog." => "nhưng có một người thợ săn và chú chó đi qua.",
    "  but they also made me want to kill." => "nhưng những từ đó cũng làm tôi muốn được giết.",
    "  but they're always lying, so be careful" => "nhưng chúng luôn nói dối, nên hãy cẩn thận",
    "  by way of the witch's magic." => "dưới ma thuật của phù thủy.",
    "  contact with poison, making them quite useful." => "tiếp xúc với chất độc, nên rất hữu ích.",
    "  dead in the wreckage." => "là đã chết trong đống đổ nát.",
    "  deep in the depths of the house." => "ở nơi sâu thẳm nhất trong căn nhà.",
    "  didn't love me." => "không hề yêu thương tôi.",
    "  doesn't necessarily mean we're immortal.\"" => "không có nghĩa là chúng tôi là loài bất tử.",
    "  fed to the demon, and thus lack any will." => "đã bị hiến cho quỷ, nên không còn ý chí.",
    "  for his elderly mother still at home." => "cho người mẹ già đang ở nhà.",
    "  for spells of this type to succeed." => "để bùa chú loại này có thể thành công.",
    "  from the forest. Hope to see you home soon." => "khu rừng ra nhé. Mong sớm gặp lại con ở nhà.",
    "  granted to a witch by a demon." => "được ban cho phù thủy bởi ác quỷ.",
    "  has gone back to her.\"" => "đã quay trở lại với cô ta.\"",
    "  have long enjoyed dining with silverware." => "từ lâu đã thích dùng dao nĩa bằng bạc.",
    "  he looked \\c[9]forward\\c[0], \\c[9]right\\c[0], \\c[9]left\\c[0], \\c[9]forward\\c[0], \\c[9]right\\c[0], \\c[9]left\\c[0]..." => "anh nhìn về \\c[9]phía trước\\c[0], \\c[9]phải\\c[0], \\c[9]trái\\c[0], \\c[9]phía trước\\c[0], \\c[9]phải\\c[0], \\c[9]trái\\c[0]...",
