    "  her share of love.\"" => "tất cả tình yêu thương của nó.\"",
    "  hire servants to demonstrate their wealth." => "thuê người hầu để phô trương sự giàu có.",
    "  inside the glass case." => "bên trong chiếc lồng kính.",
    "  inspectors to believe that they" => "Các điều tra viên tin rằng đây là một vụ mưu sát.",
    "  is referred to as a \"witch.\"" => "cũng sẽ được gọi là một \"Phù thủy\".",
    "  just by having them in your possession." => "chỉ cần bạn mang theo bên mình.",
    "  mind if you go to her house, but just stay away" => "cấm con qua nhà bạn chơi, nhưng hãy tránh xa",
