    "  needs to have sincere consent." => "cần phải có sự đồng thuận chân thành.",
    "  no matter what body they've got.\"\\.\\." => "cho dù họ có ở trong cơ thể nào đi nữa.\"\\.\\.",
    "  no matter what body they\\'ve got.\"\\.\\." => "cho dù họ ở trong cơ thể nào đi nữa.\"\\.\\.",
    "  of the mother who chose to abandon her." => "từ người mẹ đã bỏ rơi cô ấy.",
    "  of your own accord, y'know?\"" => "theo ý mình được đâu, biết không?\"",
    "  of your own accord, y\\'know?\"" => "theo ý muốn của mình đâu, biết không?\"",
    "  or if the house eats you alive.\"" => "hay bị ngôi nhà này ăn sống.\"",
    "  physical forms doesn't make us immortal.\"" => "thể xác đâu có nghĩa là chúng tôi bất tử.\"",
    "  physical forms doesn\\'t make us immortal.\"" => "xác thịt đâu có nghĩa là chúng tôi bất tử.\"",
    "  playing with some yarn." => "đùa giỡn với cuộn len tròn.",
    "  promise that, and maybe not.\"" => "Có lẽ tôi đã hứa điều đó, và cũng có lẽ không.\"",
    "  pulling along a cart full of treasure." => "kéo theo một cỗ xe chứa đầy của cải.",
    "  regardless of what body they're in.\"\\.\\." => "bất kể người ấy ở trong cơ thể nào đi nữa.\"\\.\\.",
