    "  secrets of the house's inhabitants..." => "bí mật của những cư dân trong nhà...",
    "  so it is suspected they were murdered" => "nên bị nghi ngờ là đã bị sát hại",
    "  so they cannot kill humans directly." => "nên chúng không thể trực tiếp giết người được.",
    "  so... I was worried about you." => "nên... bố đã rất lo cho con.",
    "  someone would love her." => "được một ai đó yêu thương.",
    "  something stupid again, as usual...\"" => "gì đó ngu ngốc như mọi khi nữa cho xem....\"",
    "  that gloomy woman again?\"" => "con ả có mặt như đưa đám kia nữa nhé?\"",
    "  that'll get you through easy. \\.Didja know?\"" => "qua chỗ này một cách dễ dàng không?\"",
    "  the forest, and kidnaps children who get lost there." => "khu rừng, và bắt cóc những đứa trẻ bị lạc.",
