    "  to trade bodies with you.\"" => "thuật để hoán đổi cơ thể với cậu đấy.\"",
    "  to which the hunter agreed." => "và người thợ săn đã đồng ý.",
    "  was a girl who was loved." => "là một cô gái được tràn ngập tình thương.",
