    "  who gave it to me.\\!" => "cho tớ cơ thể này mà.",
    "  who would die for her sake." => "phải chết vì lợi ích của cô ấy.",
    "  with all the notes and whatnot.\"" => "với tất cả các nốt nhạc các thứ.\"",
    "  with those great big arms?\"" => "với đôi cánh tay to lớn đó sao?\"",
    "  without any help from me, can't you?\"" => "sự trợ giúp nào của ta mà, đúng không?\"",
    "  without one bit of my assistance.\"" => "mà chẳng cần một chút trợ giúp nào từ tôi.\"",
    "  women can have either \\c[14]blonde\\c[0] or \\c[10]red hair\\c[0]." => "phụ nữ có thể có tóc \\c[14]vàng\\c[0] hoặc \\c[10]đỏ\\c[0].",
    "  women in this region in particular." => "người phụ nữ sống ở những nơi khác nhau.",
    "  would be a \"witch\" forever." => "và cô ấy sẽ vĩnh viễn trở thành một \"phù thủy\".",
