    " \".....Thank you.\"" => "\".....Cảm ơn cô.\"",
    " \"...Ah, that's right. I must warn you.\\!" => "\".... À phải rồi. Ta đang cảnh báo cô!",
    " \"...Can't someone shut it up?\"" => "\"....Ai đó khiến nó ngậm mồm lại được không?\"",
    " \"...Come to think of it," => "\"... Nghĩ cho kĩ thì,",
    " \"...Do not disturb the keeper of time.\"" => "\"....Đừng làm phiền người canh gác thời gian.\"",
    " \"...Don't bother me.\"" => "\"...Đừng làm phiền ta.\"",
    " \"...Enough already.\"" => "\"... Thôi đủ rồi.\"",
    " \"...Even from the next room over," => "\"....Cách cả một phòng,",
    " \"...HEY! \\....\\. ...Gimme that.\"\\!" => "\"...Này! \\....\\. ...Đưa tao cái đó.\"\\!",
    " \"...Heehee, just kidding. Here you are.\"" => "\"...Heehee, đùa chút thôi. Của cô đây.\"",
    " \"...Heehee. \\.I guess I did say that.\"" => "\"...Hihi. \\.Chắc tôi có nói thế thật.\"",
    " \"...Huh? What is it?" => "\"...Hửm? Cái gì đây?",
    " \"...I told you to just be silent.\"" => "\"...Tôi đã bảo cô im lặng rồi mà.\"",
    " \"...Just give that to a cat or something.\"" => "\"...Đưa cái thứ này cho con mèo ấy, mặc kệ tôi đi.\"",
    " \"...My... my ring...\"" => "\".... Nhẫn.... Nhẫn của ta....\"",
    " \"...Need my help?\"" => "\"...Cần tôi giúp không?\"",
    " \"...Oho. I don't hear that racket anymore.\"" => "\"....oho. Hết ồn ào rồi.\"",
    " \"...Thank you. \\!...Take this.\"" => "\"... Cảm ơn.\\!... Hãy nhận lấy vật này.\"",
    " \"...Then be silent.\"" => "\".....Và cuối cùng là vẫn tiếp tục giữ im lặng.\"",
    " \"...There is nothing I can do for you." => "\"...Tôi chẳng thể làm gì cho cô được đâu.",
    " \"...Viola?\"" => "\"...Viola?\"",
    " \"...Well, I need nothing from you." => "\"....Chà, ta thì không cần gì ở cô cả.",
    " \"...What am I supposed to do with that?\"" => "\"...Tôi sẽ làm được gì với cái thứ này chứ?\"",
    " \"...You need something?\"\\!" => "\"...Cô cần gì sao?\"\\!",
    " \"...You probably shouldn't have come in here" => "\"...Lẽ ra cô không nên bước vào đây",
    " \"...\\. ...\\!Yes, I understand." => "\"...\\. ...\\!Được rồi, tôi đã hiểu.",
    " \"...\\. Ahh, \\.yes.\\. This is... \\!heheh. \\.Mine." => "\"...\\. Ahh, \\.Đúng rồi.\\. Cái này là... \\!heheh. \\.Của tao.",
    " \"...\\....\\...Ahh... \\.aah?\\! ...?\\. Wait a sec.\\!" => "\"...\\....\\...Ahh... \\.aah?\\! ...?\\. Khoan đã.\\!",
    " \"...\\| ...\\| This is it...\"" => "\"...\\| ...\\| Đây là nó...\"",
    " \"...\\| ...\\| This is my...\"" => "\"...\\| ...\\| Đây là của tôi...\"",
    " \"...\\|Having fun there?\"" => "\"...\\|Ở đó có vui không?\"",
    " \".\\..\\..\\..Hmm, I dunno.\\!" => "\".\\..\\..\\..Hmm, tôi không biết.\\!",
