    " \"A cat statue.\\!" => "\"Một bức tượng hình mèo.\\!",
    " \"A decorative cat ornament." => "\"Một vật trang trí hình mèo.",
    " \"A hand is exactly what I needed.\"" => "\"Thứ tôi đang cần lúc này chính xác là một bàn tay.\"",
    " \"A snake ate him.\"" => "\"Một con rắn đã ăn thịt ông ấy.\"",
    " \"AHAHAHAHAHAHAHAHA, AHA-HA-HAHAHAHAHA!!!!!\"\\|\\^" => "\"AHAHAHAHAHAHAHAHA, AHA-HA-HAHAHAHAHA!!!!!\"\\|\\^",
    " \"Aaaaah... dammit...\"" => "\"Aaaaah... chó chết...\"",
    " \"After all, \\.\\.it's my house, yes?\\!" => "\"Dù sao thì, \\.\\.đây cũng là nhà của tao mà, đúng không?\\!",
    " \"Ah!\"" => "\"A!\"",
    " \"Ah, \\.\\.could it be...\\!" => "\"A, \\.\\.lẽ nào là...\\!",
    " \"Ahem, you there!\"" => "\"Này, cô kia!\"",
    " \"Ahem, you there!\\!" => "\"Này, cô kia!\\!",
    " \"Ahh, I'm busy, so busy...\"" => "\"Ahh, ta đang bận, rất bận...\"",
    " \"Ahh, I'm busy, so busy...\"\\!" => "\"Aaa, tôi bận lắm, bận rộn lắm...\"\\!",
    " \"Ahh, so busy...\"" => "\"Aaa, bận rộn quá đi...\"",
    " \"Ain't I just the nicest?\"" => "\"Tôi là chú mèo tốt bụng nhất có phải không?\"",
    " \"Although with the house givin' you notes" => "\"Mặc dù ngôi nhà đã cho cô gợi",
    " \"And I'll \\.\\s[4]take\\s[0] her share of love, too.\"" => "\"Và tao cũng sẽ \\.\\s[4]cướp lấy\\s[0] tình yêu của nó nữa.\"",
    " \"And I'll take her share of love, too.\"" => "\"Và tao cũng sẽ nhận lấy phần tình yêu đó từ mày.\"",
    " \"And I\\'ll \\.\\s[4]take\\s[0] her share of love, too.\"" => "\"Và tao cũng sẽ \\.\\s[4]chiếm đoạt\\s[0] tình yêu của nó nữa.\"",
    " \"And he even sent you that letter." => "\"Và ông ấy còn gửi cho mày lá thư đó nữa.",
    " \"And it seems the magic of the house" => "\"Và có vẻ như ma thuật của ngôi nhà",
    " \"Are you that worried about your father?\"" => "\"Cô lo lắng cho cha cô đến thế sao?\"",
    " \"Because \"she\" showed up, it looks like.\"" => "\"Vì có vẻ như \"cô ta\" đã xuất hiện rồi.\"",
    " \"Besides, you're the one" => "\"Với lại, cậu là người",
    " \"Book of Death\"\\!" => "\"Cuốn Sách Tử Thần\"\\!",
    " \"Boy, you're stubborn.\"\\|\\|" => "\"Chà, cô bướng bỉnh thật đấy.\"\\|\\|",
    " \"But don't worry! I'm with you!\\!" => "\"Nhưng đừng lo! Tôi sẽ bên cạnh cô!\\!",
    " \"By the way, this is a witch's house." => "\"Nhân tiện, đây là ngôi nhà phù thủy.",
    " \"Cats are just so elegant.\\." => "\"Loài mèo lúc nào cũng tao nhã.\\.",
    " \"Decided I'd follow you for laughs." => "\"Tôi quyết định đi theo cô cho vui thôi.",
    " \"Decided I'd follow you for laughs.\\fs[27]" => "\"Ta quyết định sẽ đi theo cô để cho vui.\\fs[27]",
    " \"Demons\" feed on human souls." => "\"Ác quỷ\" ăn linh hồn con người.",
    " \"Didja really have to fire \\v[129] times?\"" => "\"Cô nhất thiết cần phải bắn \\v[129] nhiều vậy sao?\"",
    " \"Don't tell me... Has she gone to see" => "\"Đừng nói với tôi... Rằng cô ấy lại đi gặp",
    " \"Eh, well, good luck with that.\"" => "\"Eh,vậy chúc cô may mắn.\"",
    " \"Either one's fine by me, \\.yeah?\\!" => "\"Vì cả hai đều có lợi cho tôi, yeah?!",
    " \"Enjoy your stay.\"" => "\"Tận hưởng chuyến đi nhé.\"",
    " \"Eyedrops\"" => "\"Nước nhỏ mắt\"",
    " \"Geez, that's annoying!\"" => "\"Geez, ồn ào thật!\"",
    " \"Geez, you freaked me out!" => "\"Geez,cô làm tôi buồn đấy!",
    " \"Get a grip already!\"" => "\"Ý thức chút coi nào!\"",
    " \"Gonna be sayin' bye-bye to you soon.\"" => "\"Sắp phải chia tay rồi.\"",
    " \"Good luck with the rest, \\.Ellen.\\!" => "\"Chúc cô may mắn quãng đường con lại, \\.Ellen.\\!",
    " \"Good, now I can sleep in peace.\"" => "\"Tốt, giờ ta có thể ngủ mà không bị làm phiền rồi.\"",
    " \"H-Hey!" => "\"N-Này!",
    " \"He can't even go back to the earth now.\"" => "\"Giờ thì ông ấy không thể quay trở về được nữa.\"",
    " \"He was looking for a home to go back to...\"" => "\"Ông ta chỉ muốn tìm một ngôi nha để trở về thôi mà....\"",
    " \"He\" told XXX:" => "\"Hắn ta\" nói với XXX:",
    " \"Head??? Medicine\"" => "\"Đầu??? thuốc....",
    " \"Headache Medicine\"" => "\"Thuốc nhức đầu\"",
    " \"Heard a loud crash. Something happen?\"" => "\"Ta nghe thấy tiếng động lớn. Có gì xảy ra à?\"",
    " \"Hey, by the way. Remember that hallway" => "\"Hey, mà nhân tiện. Cô còn nhớ cái hành lang",
    " \"Hm. Well. That's that.\"" => "\"Hm. Được rồi. Chỉ vậy thôi.\"",
    " \"Hm? \"\\s[4]Give it back?\\s[0]\"\\! No way.\\!" => "\"Hửm? \"\\s[4]Trả lại à?\\s[0]\"\\! Không đời nào.\\!",
    " \"Hm? Ah yes, our promise. Here you are.\"" => "\"Hửm? À đúng rồi, lời hứa của chúng ta. Của cô đây.\"",
    " \"Hm? Pollen? \\!Maybe we did" => "\"Hm? Cánh hoa? \\!",
    " \"Hm? Why am I here?" => "\"Hmm? Tại sao ta lại ở đây?",
    " \"Hmm.\\!" => "\"Hừm.\\!",
    " \"Honestly, she's such a nuisance.\"" => "\"Thật tình mà nói, cô ta đúng là một tên phiền phức.\"",
    " \"How do you do?\"" => "\"Chào bạn, dạo này bạn khỏe không?\"",
    " \"How do you do?\"\\!" => "\"Xin chào?\"\\!",
    " \"How long are you going to chase me?\\!" => "\"Mày còn định đuổi theo tao đến bao giờ nữa hả?\\!",
    " \"Huh, what?\\." => "\"Huh, sao thế?\\.",
    " \"Huh? Back already?\"" => "\"Huh? Quay lại rồi à?\"",
    " \"Huh? Back so soon?\"" => "\"Hửm? Quay lại sớm thế?\"",
    " \"Huh? Really now?\\!" => "\"Huh? Thật sao?",
    " \"Humans shouldn't be out here." => "\"Con người không nên lảng vảng quanh đây.",
    " \"I bet he's up to" => "\"Tôi cá là hắn sẽ làm",
    " \"I can't SMOKE it\\< without one!!\\.\"" => "\"Tao không thể HÚT \\<nếu không có nó!!\\.\"",
    " \"I don't need your help!\"" => "\"Tôi không cần cô giúp!\"",
    " \"I don't particularly care if you get out of here" => "\"Tôi không quan tâm việc cô có thể thoát khỏi đây",
    " \"I forget what exactly the proper way to X is..." => "\"Tôi không nhớ chính xác làm thể nào để X...",
    " \"I heard it! I heard her ugly wail!\"" => "\"Bố nghe thấy rồi! Bố nghe thấy tiếng thét kinh tởm của nó!\"",
    " \"I heard it!\"\\^" => "\"Bố nghe thấy rồi!\"\\^",
    " \"I imagine it'd be quite easy for you to" => "\"Tôi có thể dễ dàng hình dung ra được cảnh tưởng",
    " \"I knew you wouldn't need my help one bit.\"" => "\"Tôi biết thừa cô chẳng cần chút giúp đỡ nào mà.\"",
    " \"I knowww, right?\"" => "\"ĐIỀU ĐÓ AI KHÔNG BIẾTTT ?\"",
    " \"I quite like a black cat's body.\"" => "\"Tôi khá thích cơ thể mèo đen này đấy.\"",
    " \"I thought you wouldn't need my help.\"" => "\"Cứ tưởng cô sẽ không cần sự giúp đỡ của tôi.\"",
    " \"I told you to watch the cart," => "\"Tao đã bảo mày phải canh cỗ xe mà,",
    " \"I was guided by that house all the way.\\!" => "\"Ngôi nhà đã dẫn đường cho tôi suốt chặng đường.\\!",
    " \"I was surprised you could trap me with" => "\"Tôi khá ngạc nhiên khi cô có thể bẫy được tôi bằng",
    " \"I wouldn't think you'd need my help.\"" => "\"Tôi không nghĩ cô lại cần tôi giúp đâu.\"",
    " \"I'd hope so.\\!" => "\"Tôi cũng mong là vậy.\\!",
    " \"I'd\\w[1] rather\\w[1] YOU\\w[1] lent\\w[1] me\\w[1] a\\w[1] hand\\w[1].\"" => "\"Tôi \\.\\.muốn\\.\\. mượn\\.\\. tay\\.\\. của\\.\\.\\. CÔ.\"",
    " \"I'm gonna leave one step ahead of you.\\!" => "\"Tôi sẽ đi trước cô một bước.\\!",
    " \"I'm just glad you're okay.\\!" => "\"Ta mừng vì con vẫn ổn.\\!",
    " \"If someone did... Ah, yes." => "\"Nếu có ai đó X cô ta.... À, phải rồi.",
    " \"Is that you, Viola?! Are you safe?!" => "\"Con đấy à, Viola?!\\.\\. Con không sao chứ?!\\.\\.",
    " \"It can always tell who its master is," => "\"Nó luôn biết ai là chủ nhân thực sự của nó,",
    " \"It'll be a pity when you're gone.\\." => "\"Sẽ thật đáng tiếc khi cô đi mất.\\.",
    " \"It'll be just fine.\\!" => "\"Mọi chuyện rồi sẽ ổn thôi mà.\\!",
    " \"Just for a day?\\|\\." => "\"Chỉ trong một ngày?\\|\\.",
    " \"Just give it up already.\"\\|\\|" => "\"Hãy từ bỏ đi.\"\\|\\|",
    " \"Just need a li'l... \\.Please.\"" => "\"Chỉ một ít thôi... làm ơn.\"",
    " \"Just so you know...\"" => "\"Để tôi cho cô biết.....\"",
    " \"Just think! Without her, we would be" => "\"Hãy nghĩ mà xem! Nếu không có cô ta, thì chúng ta",
    " \"Let me show my appreciation.\"" => "\"Hãy để tôi tỏ lòng biết ơn của mình.\"",
    " \"Me? \\!I don't know much about her.\\." => "\"Tôi? Tôi không biết gì nhiều về cô ấy.",
    " \"Might as well, if you can't leave.\"" => "\"Cũng phải thôi, nếu cô không thể rời đi.\"",
    " \"My dad is dead.\"" => "\"Bố cháu đã chết rồi.\"",
    " \"My dad was eaten by a snake.\"" => "\"Bố cháu đã bị một con rắn nuốt chửng.\"",
    " \"My dad's dead.\"" => "\"Cha chúng tôi chết rồi.\"",
    " \"My ring..." => "\"Nhẫn của ta....\\.\\.",
    " \"Naturally, you can get out of this house" => "\"Đương nhiên là cô có thể ra khỏi ngôi nhà này",
    " \"Nausea ...\"" => "\"Buồn nôn quá...\"",
    " \"None of the three ways to X are proper." => "\"Rõ ràng là không còn cách nào để có thể X nó.",
