    " \"You look lost, so here's a hint.\"" => "\"Có vẻ cô đang bị lạc, tôi sẽ cho cô một ít gợi ý.\"",
    " \"You never asked me for help, even once." => "\"Cô chưa bao giờ nhờ tôi giúp gì cả.",
