    " Old, cobweb-infested shelves." => "Những chiếc kệ cũ kỹ đầy mạng nhện.",
    " On the door is a window the size of your palm." => "Một cánh cửa có kích thước chỉ bằng lòng bàn tay bạn.",
    " Once the witch shows herself," => "khi phù thủy tìm thấy được bản thân mình,",
    " Once upon a time, there was a rich man" => "Ngày xửa ngày xưa, có một phú ông",
    " Once upon a time, there was a rich man\npulling along a cart full of treasure.\nHis cart broke down in the woods,\nbut then a hunter and his dog came along.\nThe rich man pleaded to the hunter\nto keep a close eye on his cart,\nto which the hunter agreed.\nThe rich man went to get a new cart.\nMeanwhile, the hunter kept watch.\nNight soon fell, and the hunter grew worried\nfor his elderly mother still at home.\nSo the hunter told the dog to watch the cart\nand went home to check on his mother.\nWhen the man returned, \\!he saw the dog on guard.\\!\nSo he gave the dog a reward for his master,\na silver coin, to carry in his mouth.\nThe dog ran all the way home\nand brought his master the coin.\\!\nBut the hunter flew into a rage.\n\"I told you to watch the cart,\nand what did you do? You stole from it!\"\\.\\.\nSo the master killed the dog." => "Ngày xửa ngày xưa, có phú ông\nđẩy một xe kéo chứa đầy tiền.\nBỗng dưng chiếc xe kéo bị hỏng giữa rừng, nhưng một\nlúc sau một thợ săn đi cùng một con chó đi ngang qua.\nNgười đàn ông đó đã van nài người thợ săn\nrằng hãy trông chừng chiếc xe kéo chứa tiền\nĐể người phú ông đó đi lấy một chiếc xe kéo khác,\nvà người thợ săn đã đồng ý.\nTrong khi đó,người thợ săn sẽ giữ chiếc đồng hồ.\nKhi đêm gần xuống, và thợ săn lo lắng cho\ncho người mẹ già đang chờ ở nhà.\nVì thế người thợ săn đã bảo chú chó ở lại canh gát\ncho tới khi phú ông quay lại và chạy về nhà để chăm\nsóc cho mẹ.\nMột lúc sau phú ông quay lại, ông ấy thấy con chó\nvẫn đang đứng canh gác thế nên ông ấy đã tặng cho\nngười thợ săn một đồng bạc, và đặt vào miệng chú\nchó để mang về cho chủ nhân mình.\nChú chó đã chạy khắp nơi tìm đường về và khi về\nchú chó đã đưa cho chủ nhân đồng bạc ấy.\nNhưng thay vì được xoa đầu cảm ơn thì\nngười thợ săn đã nổi giận.\n\"TAO ĐÃ BẢO MÀY Ở LẠI ĐÓ TRÔNG CHỪNG XE KÉO,\nCHỨ KHÔNG PHẢI BẢO MÀY ĐI CƯỚP TIỀN NGƯỜI KHÁC.\"\n\nVà thế là người thợ săn đã giết chú chó.",
