    " The \\c[14]yellow flowers\\c[0] are lovely to a fault.\nThe pollen produced by these flowers is\n\\fs[27]a prized medicine that can both save and take lives.\\fs[29]" => "Những \\c[14]bông hoa vàng\\c[0] đáng yêu đến\nmức bạn không thể tin vào mắt mình.\n\\c[10]Phấn hoa từ những bông hoa này được dùng làm\n\\fs[27]dược phẩm mà vừa có thể cứu lấy\n\\c[10]\\fs[27]cũng như vừa có thể lấy đi một sinh mạng.\\fs[29]",
