    " The window is shut fast." => "Cửa sổ đóng chặt.",
    " The window is shut fast.\\." => "Cửa sổ đóng chặt.\\.",
    " The witch's house devours humans\nand offers their souls up to a demon." => "Ngôi nhà của phù thủy sẽ ăn thịt con người và linh\nhồn của những kẻ xấu số đó sẽ thành bữa ăn cho\nác quỷ.",
    " The witch's house devours humans." => "Ngôi nhà phù thủy nuốt chửng con người.",
    " The witch's house has a will of its own." => "Ngôi nhà phù thủy có ý chí của riêng nó.",
    " The witch's house has a will of its own.\nIts residents are the remnants of souls\nfed to the demon, and thus lack any will." => "Ngôi nhà của phù thủy có một ý chí riêng của\nriêng nó.\nNó là tàn dư linh hồn của những kẻ đã trở thành\nbữa ăn của ác quỷ.\nNhưng vì đã bị ăn nên nó thiếu mất một phần\ný chí để tự vận hành được.",
    " The witch's house is magic," => "Ngôi nhà phù thủy là ma thuật,",
    " The witch's house is magic,\ngranted to a witch by a demon." => "Ngôi nhà của phù thủy như là một phép thuật,\nđược ác quỷ trao cho những kẻ đã lập khế ước\nvới hắn.",
    " The woman is gone from it." => "Người phụ nữ đã biến mất khỏi đó.",
    " The woman spit something out." => "Người phụ nữ đưa thứ gì đó ra.\n",
    " The yellow flower lies in cut-up pieces." => "Bông hoa vàng nằm đứt đoạn từng khúc.",
    " The yellow flower's been sliced to bits." => "Những bông hoa vàng bị sắc thành từng mảnh nhỏ.",
    " The yellow flowers are having a fun chat." => "Những bông hoa vàng đang có cuộc trò chuyện vui vẻ.",
    " The yellow flowers are having pleasant conversation." => "Những bông hoa vàng đang trò chuyện rôm rả.",
    " Their bodies were found to have stab wounds," => "Thi thể của họ có nhiều vết đâm,",
    " Their eye colors depend on their hair color.\\!" => "\\>  Màu mắt của mỗi người phụ thuộc vào màu tóc của họ.",
    " Their eye colors depend on their hair color.\\hold\\^" => "Màu mắt của họ phụ thuộc vào màu tóc.\\hold\\^",
    " Their souls are offered to a demon." => "Linh hồn họ bị hiến tế cho ác quỷ.",
    " Then I fed them all to the house." => "Và tôi đem hết tất cả chúng làm thức ăn cho ngôi nhà.",
    " There are bloody scissors on the workbench." => "Cây kéo bị dính máu.",
    " There are cracked bottles up on the shelf." => "Một chai lọ bị nứt được đặt trên kệ.",
    " There are empty bottles up on the shelf." => "Có những chiếc chai rỗng trên kệ.",
    " There are some notes on the table." => "Có vài mẩu giấy ghi chú trên bàn.",
    " There was once a soldier.\\!" => "Ngày xưa từng có một người lính.\\!",
    " There was once a soldier.\\!\nUnbeknownst to him, his country had\nalready perished... and so had he.\nEven in death, the soldier patrolled.\nStarting in the \\c[14]center\\c[0] of the castle ruins,\nhe looked \\c[9]forward\\c[0], \\c[9]right\\c[0], \\c[9]left\\c[0], \\c[9]forward\\c[0], \\c[9]right\\c[0], \\c[9]left\\c[0]..." => "Ngày xưa tùng có một người lính.\nMột người lính vô danh không ai biết tới và\ncũng không ai biết nơi anh ấy sinh ra....\nMột ngày nọ anh lính ấy đã bị địch tấn công.....\nvà anh ta đã tử trận.\nThậm chí sau khi chết, người lính vẫn thực hiện\nnhiệm vụ tuần tra của mình.\nBắt đầu từ \\c[14]trung tâm\\c[0] của lâu đài,\nAnh ta nhìn về \\c[9]phía trước\\c[0], \\c[9]phải\\c[0], \\c[9]trái\\c[0], \\c[9]phía trước\\c[0],\n\\c[9]phải\\c[0], \\c[9]trái\\c[0].....",
    " There's a 12 card with a queen on it," => "Có 12 thẻ bài với nữ hoàng trên đó,",
    " There's a big dragging mark on the floor." => "Một vật gì đó khá lớn đã bị kéo lê\nvà để lại vết kéo trên sàn nhà.",
    " There's a blue-winged butterfly model in the case.\\!" => "Có mô hình bướm cánh xanh trong hộp kính.\\!",
    " There's a book titled \"Book of Death.\"" => "Tên cuốn sách \"Cuốn sách tử thần\".",
    " There's a giant snake." => "Một con rắn to lớn.",
    " There's a hole and an iron ladder going down." => "Có một cầu thang sắt dẫn xuống phía dưới.",
    " There's a hole just big enough to crawl in.\\!" => "Có một cái lỗ vừa đủ để chui vào.\\!",
    " There's a hole.\\!" => "Có một cái lỗ.\\!",
    " There's a little bit of room left." => "Vẫn còn một khoảng trống nhỏ.",
