    " \\CL \\c[10]\\fs[25]YOU WORE THEM, YOU WORE THEM, AHAHAHAHA\\fs[29]" => "\n\\CL\\c[10]\\fs[25]\"NGƯƠI ĐÃ MANG CHÚNG VÀO, THẬT NGU NGỐC LÀM SAO\nAHAHAHAHAHAHAH\"\\fs[29]",
