    " \\c[10]A cute girl with golden braids." => "\\c[10]Một cô gái dễ thương với mái tóc thắt bím màu vàng óng.",
    " \\c[10]After living for several centuries as a witch," => "\\c[10]Sau nhiều thế kỉ sống như một phù thủy,",
    " \\c[10]As of now, the only name fit for her was" => "\\c[10]Giờ đây, tên gọi duy nhất hợp với cô",
    " \\c[10]Then a girl came over to play." => "\\c[10]Nhưng có một cô gái đã đến chơi với tôi.",
    " \\c[10]XXX found out." => "\\c[10]XXX đã nhận ra.",
    " \\c[11]green\\c[0], \\c[9]blue\\c[0], and \\c[10]red\\c[0].\\^" => "\\c[11]xanh lá\\c[0], \\c[9]xanh dương\\c[0], và \\c[10]đỏ\\c[0].\\^",
    " \\c[8]black\\c[0], \\c[14]gold\\c[0], and \\c[10]red\\c[0].\\hold" => "\\c[8]đen\\c[0], \\c[14]vàng\\c[0], và \\c[10]đỏ\\c[0].\\hold",
    " \\c[9]front\\c[0], \\c[9]right\\c[0], \\c[9]left\\c[0]..." => "\\c[9]trước\\c[0], \\c[9]phải\\c[0], \\c[9]trái\\c[0]...",
    " \\center..." => "\\center...",
