    " \\center...\\|Incorrect." => "\\center...\\|Sai rồi.",
    " \\center...\\|\\s[8]DID YOU ANSWER WRONG ON PURPOSE?" => "\\center...\\|\\s[8]MÀY CỐ TÌNH TRẢ LỜI SAI ĐÚNG KHÔNG?",
    " \\center12 IS THE QUEEN CARD" => "\\center12 LÀ QUÂN BÀI HOÀNG HẬU",
    " \\centerA demon came along" => "\\centerMột con quỷ đã xuất hiện",
    " \\centerAND I CAN BE A BIRD." => "\\centerVÀ TA CÓ THỂ LÀ MỘT CON CHIM.",
    " \\centerAND LET NOTHING DISTRACT YOU" => "\\centerVÀ ĐỪNG ĐỂ ĐIỀU GÌ LÀM PHÂN TÂM",
    " \\centerAm I \"a clock\"?" => "\\centerTa là \"một chiếc đồng hồ\"?",
    " \\centerAm I \"a mirror\"?" => "\\centerTa là \"một chiếc gương\"?",
    " \\centerAm I \"a plant\"?" => "\\centerTa là \"một cái cây\"?",
    " \\centerAm I \"man\"?" => "\\centerTa là \"đàn ông\"?",
    " \\centerAm I \"red\"?" => "\\centerTa là \"màu đỏ\"?",
    " \\centerAm I \"woman\"?" => "\\centerTa là \"phụ nữ\"?",
    " \\centerAnd with all that, \\.so foolish." => "\\centerVà với tất cả những điều đó, \\.thật ngu ngốc.",
    " \\centerBEARS IN THE BASKET" => "\\centerGẤU TRONG GIỎ",
    " \\centerBIRD: CUCKOO CLOCK" => "\\centerCHIM: ĐỒNG HỒ CÚC CU",
    " \\centerBIRDS EAT GREENERY" => "\\centerCHIM ĂN CÂY CỎ",
    " \\centerBLUE EYES SEE THE SCORE" => "\\centerMẮT XANH NHÌN BẢN NHẠC",
    " \\centerBecause it kept me from going outside." => "\\centerVì nó khiến tôi không thể ra ngoài.",
    " \\centerBecause it made no one love me." => "\\centerVì nó khiến không một ai yêu thương tôi.",
    " \\centerBecause she would save me" => "\\centerVì cô ấy sẽ cứu tôi",
    " \\centerBut it wasn't enough." => "\\centerNhưng nó vẫn chưa đủ.",
    " \\centerCOME TO MY ROOM" => "\\centerHÃY ĐẾN PHÒNG TA",
    " \\centerDESTROY THE PAINTING" => "\\centerHÃY PHÁ HỦY BỨC TRANH",
    " \\centerDIE?" => "\\centerCHẾT?",
    " \\centerDO YOU LIKE FROGS?" => "\\centerMÀY CÓ THÍCH ẾCH KHÔNG?",
    " \\centerELDERLY MAN: GRANDFATHER CLOCK" => "\\centerÔNG LÃO: ĐỒNG HỒ QUẢ LẮC",
    " \\centerGO WHERE ONLY ONE EYE IS OPEN" => "\\centerĐI ĐẾN NƠI CHỈ CÓ MỘT MẮT MỞ",
    " \\centerHE CAN'T EVEN TELL COLORS APART" => "\\centerNÓ THẬM CHÍ CÒN KHÔNG PHÂN BIỆT ĐƯỢC MÀU SẮC",
    " \\centerHE'S HUNGRY" => "\\centerNÓ ĐANG ĐÓI",
    " \\centerI CAN BE THE SUN. I CAN BE SAND." => "\\centerTA CÓ THỂ LÀ MẶT TRỜI. TA CÓ THỂ LÀ CÁT.",
    " \\centerI CAN EVEN BE AN ELDERLY MAN." => "\\centerTA THẬM CHÍ CÓ THỂ LÀ MỘT ÔNG LÃO.",
    " \\centerI X all the friends who" => "\\centerTôi đã giết tất cả những người bạn",
    " \\centerI don't like my illness." => "\\centerTôi ghét căn bệnh của mình.",
    " \\centerI was sick," => "\\centerTôi bị bệnh,",
    " \\centerI wouldn't X her." => "\\centerTôi sẽ không giết cô ấy.",
    " \\centerI'll teach you a spell to cure your illness." => "\\centerTa sẽ dạy ngươi thần chú chữa lành bệnh.",
    " \\centerI've been in this house ever since." => "\\centerTôi đã sống trong ngôi nhà này kể từ khi đó.",
    " \\centerIf you let me eat more people," => "\\centerNếu ngươi cho ta ăn thêm nhiều người,",
    " \\centerIt hurts all over." => "\\centerNó đau đớn khắp cả người.",
    " \\centerIt thanked me for the meal" => "\\centerNó cảm ơn tôi vì bữa ăn",
    " \\centerLEND A HAND" => "\\centerHÃY GIÚP MỘT TAY",
    " \\centerLET THEM BLEED" => "\\centerHÃY ĐỂ CHÚNG CHẢY MÁU",
    " \\centerMAKE A MIRROR IMAGE" => "\\centerTẠO MỘT HÌNH ẢNH PHẢN CHIẾU",
    " \\centerMAKE SOUND IN FOUR ROOMS" => "\\centerTẠO ÂM THANH TRONG BỐN PHÒNG",
    " \\centerMEDICINE" => "\\centerTHUỐC",
    " \\centerMy father and my mother" => "\\centerCha và mẹ của tôi",
    " \\centerPASS WITH COLORLESS SHOES" => "\\centerBƯỚC QUA VỚI ĐÔI GIÀY KHÔNG MÀU",
    " \\centerPLAY THE MUSIC BOX WITH 12" => "\\centerCHƠI HỘP NHẠC VỚI SỐ 12",
    " \\centerRETURN THINGS TO WHERE THEY WERE" => "\\centerTRẢ MỌI THỨ VỀ VỊ TRÍ CŨ",
    " \\centerROPE IN A BARREL" => "\\centerDÂY THỪNG TRONG THÙNG",
    " \\centerSAVE THE BUTTERFLY" => "\\centerCỨU CON BƯỚM",
    " \\centerSEE? YOU NEEDED NOT PLAY" => "\\centerTHẤY CHƯA? CÔ ĐÂU CẦN PHẢI CHƠI",
    " \\centerSOMETHING TO USE THE MEDICINE" => "\\centerTHỨ GÌ ĐÓ ĐỂ DÙNG THUỐC",
    " \\centerSUN: SUNDIAL; SAND: HOURGLASS;" => "\\centerMẶT TRỜI: ĐỒNG HỒ MẶT TRỜI; CÁT: ĐỒNG HỒ CÁT;",
    " \\centerSo I X them." => "\\centerNên tôi đã X họ.",
    " \\centerSo I made her my \"friend.\"" => "\\centerNên tôi đã biến cô ấy thành \"bạn\" của mình.",
    " \\centerStory of the Witch" => "\\centerCâu Chuyện Của Phù Thủy",
    " \\centerTASTE POISON" => "\\centerNẾM ĐỘC",
    " \\centerTHE COOK IS BUSY" => "\\centerĐẦU BẾP ĐANG BẬN",
    " \\centerTHE HALL IS POISON" => "\\centerHÀNH LANG LÀ CHẤT ĐỘC",
    " \\centerTHE SPIDER HAS POOR EYES" => "\\centerMẮT NHỆN RẤT KÉM",
    " \\centerTHE WATER IS SEALED BY THE SKULLS" => "\\centerNGUỒN NƯỚC BỊ PHONG ẤN BỞI HỘP SỌ",
    " \\centerTHROUGH THE NEXT DOOR" => "\\centerQUA CÁNH CỬA TIẾP THEO",
    " \\centerThe demon said..." => "\\centerCon quỷ đã nói...",
    " \\centerThe demon took me to this forest." => "\\centerCon quỷ đưa tôi đến khu rừng này.",
    " \\centerThen I became a witch." => "\\centerRồi tôi trở thành phù thủy.",
    " \\centerThey were all eaten by the house." => "\\centerTất cả đều bị ngôi nhà nuốt chửng.",
    " \\centerWHAT AM I?" => "\\centerTA LÀ AI?",
    " \\centerWhen I X my father and mother..." => "\\centerKhi tôi giết cha và mẹ mình...",
    " \\centerWould my power not vanish?" => "\\centerLiệu sức mạnh của tôi có biến mất không?",
    " \\centerWould not this medicine wilt my flowers?\\!" => "\\centerChẳng phải thứ thuốc này sẽ làm héo hoa của ta sao?\\!",
    " \\centerYOU NEED NOT PLAY" => "\\centerCÔ KHÔNG CẦN PHẢI CHƠI",
    " \\center\\.Viola, \\.I'm sure you'll be surprised." => "\\center\\.Viola, \\.chắc chắn mày sẽ ngạc nhiên lắm đấy.",
    " \\center\\.\\.\\s[1]So kind, \\.so charming, \\.so loved.\\.\\.\\." => "\\center\\.\\.\\s[1]Thật tốt bụng, \\.thật đáng yêu, \\.được yêu thương biết bao.\\.\\.\\.",
    " \\center\\.\\.\\s[1]So...\\." => "\\center\\.\\.\\s[1]Vậy nên...\\.",
    " \\center\\c[10]A cute girl with golden braids." => "\\center\\c[10]Một cô bé đáng yêu với mái tóc tết vàng hoe.",
    " \\center\\c[10]AND AFTER I HID IT SO WELL..." => "\\center\\c[10]VẬY MÀ TA ĐÃ GIẤU NÓ KỸ NHƯ THẾ...",
    " \\center\\c[10]FATHER DIDN'T NOTICE ME" => "\\center\\c[10]CHA KHÔNG HỀ ĐỂ Ý ĐẾN TÔI",
    " \\center\\c[10]HIDDEN IN THE DARKNESS" => "\\center\\c[10]ẨN GIẤU TRONG BÓNG TỐI",
    " \\center\\c[10]LET THEM BLEED" => "\\center\\c[10]HÃY ĐỂ CHÚNG CHẢY MÁU",
    " \\center\\c[10]MOTHER ABANDONED ME" => "\\center\\c[10]MẸ ĐÃ BỎ RƠI TÔI",
    " \\center\\c[10]Then a girl came over to play." => "\\center\\c[10]Rồi có một cô bé đến chơi cùng tôi.",
    " \\center\\c[10]WON'T YOU WEAR THE SHOES?" => "\\center\\c[10]SAO CÔ KHÔNG ĐI ĐÔI GIÀY VÀO?",
    " \\center\\c[10]X THE FLOWERS AND YOU'LL DIE TOO" => "\\center\\c[10]GIẾT HOA THÌ NGƯƠI CŨNG SẼ CHẾT",
    " \\center\\c[10]YOU WORE THEM, YOU WORE THEM, AHAHAHAHA" => "\\center\\c[10]MÀY ĐÃ ĐI CHÚNG, MÀY ĐÃ ĐI CHÚNG, AHAHAHAHA",
    " \\center\\s[1]Because \\.she's so kind." => "\\center\\s[1]Bởi vì \\.cô ấy quá tốt bụng.",
    " \\center\\s[1]Because \\.she's so trusting." => "\\center\\s[1]Bởi vì \\.cô ấy quá nhẹ dạ cả tin.",
    " \\center\\s[1]COME TO MY ROOM\\." => "\\center\\s[1]HÃY ĐẾN PHÒNG CỦA TA\\.",
    " \\center\\s[1]I'll cut off my legs.\\.\\." => "\\center\\s[1]Tao sẽ tự chặt chân mình.\\.\\.",
    " \\center\\s[1]My sickness is going to kill me.\\." => "\\center\\s[1]Căn bệnh này sắp giết chết tôi rồi.\\.",
    " \\center\\s[1]She'll give me her body..." => "\\center\\s[1]Cô ấy sẽ trao cho tôi cơ thể của mình...",
    " \\center\\s[1]So you won't be able to speak." => "\\center\\s[1]Để mày không thể cất lời nói được nữa.",
    " \\center\\s[1]\\.After all, \\.\\.\\s[2]even today... \\_" => "\\center\\s[1]\\.Dù sao thì, \\.\\.\\s[2]ngay cả hôm nay... \\_",
    " \\center\\s[1]\\.Ahh...\\. It'll be wonderful." => "\\center\\s[1]\\.Aaa...\\. Sẽ thật tuyệt vời làm sao.",
    " \\center\\s[1]\\.Because we're \"friends.\"" => "\\center\\s[1]\\.Bởi vì chúng ta là \"bạn bè\" mà.",
    " \\center\\s[1]\\.I'll live on in her body." => "\\center\\s[1]\\.Tôi sẽ sống tiếp trong cơ thể của nó.",
    " \\center\\s[1]\\.It might hurt. \\.You might cry in pain." => "\\center\\s[1]\\.Chắc sẽ đau lắm đấy. \\.Mày có thể khóc vì đau đớn.",
    " \\center\\s[1]\\.My body \\.\\.is falling apart.\\.\\." => "\\center\\s[1]\\.Cơ thể tôi \\.\\.đang dần thối rữa.\\.\\.",
    " \\center\\s[1]\\.My dear \"friend.\"" => "\\center\\s[1]\\.\"Người bạn\" thân yêu của tôi.",
    " \\center\\s[1]\\.My dear \\.\\.\\.\"friend.\"" => "\\center\\s[1]\\.\"Người bạn\" \\.\\.\\.thân yêu của tôi.",
    " \\center\\s[1]\\.\\....because we're \"friends.\"" => "\\center\\s[1]\\.\\....bởi vì chúng ta là \"bạn bè\" mà.",
    " \\center\\s[1]\\.\\.After all, I don't want to hear" => "\\center\\s[1]\\.\\.Dù sao thì tôi cũng chẳng muốn nghe",
    " \\center\\s[1]\\.\\.Ah, I know." => "\\center\\s[1]\\.\\.A, tôi biết rồi.",
    " \\center\\s[1]\\.\\.Ahhh... \\.\\.\\s[3]Viola." => "\\center\\s[1]\\.\\.Aaaa... \\.\\.\\s[3]Viola.",
    " \\center\\s[1]\\.\\.Before you come,\\.\\. I'll gouge my eyes out.\\.\\." => "\\center\\s[1]\\.\\.Trước khi mày đến,\\.\\. tao sẽ tự móc mắt mình ra.\\.\\.",
    " \\center\\s[1]\\.\\.I decided I'll take her body." => "\\center\\s[1]\\.\\.Tôi đã quyết định sẽ chiếm đoạt cơ thể nó.",
    " \\center\\s[1]\\.\\.I've gotten used to it,\\.\\." => "\\center\\s[1]\\.\\.Tôi đã quen với điều đó rồi,\\.\\.",
    " \\center\\s[1]\\.\\.If I just say it'll stop the pain,\\.\\." => "\\center\\s[1]\\.\\.Nếu tôi nói rằng nó sẽ giúp xoa dịu cơn đau,\\.\\.",
    " \\center\\s[1]\\.\\.In the garden, I'll feel a gentle breeze.\\!" => "\\center\\s[1]\\.\\.Trong khu vườn, tôi sẽ cảm nhận được làn gió nhẹ.\\!",
    " \\center\\s[1]\\.\\.She's sure to hear out my wish." => "\\center\\s[1]\\.\\.Chắc chắn cô ấy sẽ lắng nghe ước nguyện của tôi.",
    " \\center\\s[1]\\.\\.So that Viola, in my body,\\.\\.\\." => "\\center\\s[1]\\.\\.Để Viola, trong cơ thể của tôi,\\.\\.\\.",
    " \\center\\s[1]\\.\\.When we trade bodies...\\.\\." => "\\center\\s[1]\\.\\.Khi chúng tôi hoán đổi cơ thể...\\.\\.",
    " \\center\\s[1]\\.\\.\\.So then I'll give you medicine." => "\\center\\s[1]\\.\\.\\.Vậy nên tao sẽ đưa thuốc cho mày.",
    " \\center\\s[1]\\.\\.\\.Then I'll escape from this room." => "\\center\\s[1]\\.\\.\\.Rồi tôi sẽ trốn thoát khỏi căn phòng này.",
    " \\center\\s[1]\\.\\.\\.\\.That's fine, right?" => "\\center\\s[1]\\.\\.\\.\\.Như thế được chứ, đúng không?",
    " \\center\\s[2]\\.\\.Right, \\.\\.\\.Viola?" => "\\center\\s[2]\\.\\.Đúng không, \\.\\.\\.Viola?",
    " \\center\\s[3]\\.\\.A throat-burning medicine.\\.\\." => "\\center\\s[3]\\.\\.Thứ thuốc thiêu cháy cổ họng.\\.\\.",
    " \\center\\s[6]Don't go...\\|\\|\\^" => "\\center\\s[6]Đừng đi...\\|\\|\\^",
    " \\center\\s[6]Help me...\\|\\|\\^" => "\\center\\s[6]Cứu tôi với...\\|\\|\\^",
    " \\centerand ate the two of them." => "\\centervà nuốt chửng cả hai người họ.",
    " \\centerand gave me this house." => "\\centervà ban cho tôi ngôi nhà này.",
    " \\centerbut I bet you \\.won't be able to take it." => "\\centernhưng tao cá là mày \\.sẽ không chịu nổi đâu.",
    " \\centercame to my house after that." => "\\centerđến nhà tôi sau đó.",
    " \\centerdidn't love me." => "\\centerkhông hề yêu thương tôi.",
    " \\centerfrom my sickness." => "\\centernhờ thoát khỏi căn bệnh.",
    " \\centermy own screams." => "\\centertiếng la hét của chính mình.",
    " \\centerno doubt you'll drink it. \\.\\.\\.Heehee." => "\\centerchắc chắn mày sẽ uống nó thôi. \\.\\.\\.Hihi.",
    " \\centerso no one played with me." => "\\centernên chẳng ai chịu chơi với tôi cả.",
    " \\centerwill be able to despair, \\.\\.and die." => "\\centersẽ chìm trong tuyệt vọng, \\.\\.và chết đi.",
    " \\fs[26]The four eye colors are \\fs[29] \\c[20]brown\\c[0], \\c[11]green\\c[0], \\c[9]blue\\c[0], and \\c[10]red\\c[0]." => "\\fs[26]Bốn màu mắt là\\fs[29] \\c[20]nâu\\c[0], \\c[11]xanh lục\\c[0], \\c[9]xanh dương\\c[0], và \\c[10]đỏ\\c[0].",
    " \\fs[26]The four hair colors are \\fs[29] silver, \\fb\\c[15]\\oc[0]\\ow[2]black\\fr, \\c[14]gold\\c[0], and \\c[10]red\\c[0]." => "\\fs[26]Bốn màu tóc là\\fs[29] bạc, \\fb\\c[15]\\oc[0]\\ow[2]đen\\fr, \\c[14]ánh kim\\c[0], và \\c[10]đỏ\\c[0].",
    " \\fs[26]The white flowers are the most beautiful of the garden.\nOddly enough, their petals glow in the rain.\\fs[29]" => "\\fs[26]Những bông hoa trắng là loài\nhoa đẹp nhất trong khu vườn.\\fs[26]\n\\fs[29]Điều kì lạ là cánh hoa của chúng\nphát sáng khi trời mưa.\\fs[29]",
    " \\fs[27]The glass case holds what looks like a human head.\\fs[29]" => "\\fs[27]Trong tủ kính có gì đó trong khá giống đầu người.\\fs[29]",
    " \\fs[28]A piece of strawberry shortcake stuck to the table.\\fs[29]" => "\\fs[28]Một miếng bánh dâu bị dính chặt vào bàn.\\fs[29]",
    " \\fs[28]A piled stack of art collections and encyclopedias.\\fs[29]" => "\\fs[28]Một bộ sưu tập tranh vẽ và nhiều bách khoa toàn\nthư khác.\\fs[29]",
    " \\fs[28]Books on plants and crumpled balls of paper.\\fs[29]" => "\\fs[28]Sách nói về thực vật và vài mẩu giấy bị nhàu nát. \\fs[29]",
    " \\fs[28]Inserted the King key and played the music box.\\fs[29]" => "Sử dụng chìa khóa vua và phát hộp nhạc.",
    " \\fs[28]Inserted the Queen key and played the music box.\\fs[29]" => "\\fs[28]Sử dụng chìa khóa nữ hoàng và phát hộp nhạc.\\fs[29]",
    " \\fs[28]Inserted the soldier key and played the music box.\\fs[29]" => "\\fs[28]Đã tra chìa khóa của người lính\nvào và phát hộp nhạc.\\fs[29]",
    " \\fs[28]With a strange shriek, the beautiful flower expires.\\fs[29]" => "\\fs[28]Thoáng lên một tiếng hét kì lạ, bông hoa này trở\nnên héo đi.\\fs[29]",
    " \\fs[29]Viola's Dad" => "\\fs[29]Cha Viola",
    " \\hold\\B\\s[1]\\size[14]    With short \\size[18]e-book \\c[2]bonus\\c[0]:" => "\\hold\\B\\s[1]\\size[14]    Kèm truyện ngắn \\size[18]bonus: \\c[2]Độc Thoại Của Mèo Đen\\c[0]",
    " \\p[3]Open Kindle store page for" => "\\p[3]Mở trang Kindle store cho",
    " \\p[3]\\size[20]    A prequel story\\size[16] by" => "\\p[3]\\size[20]    Tiền truyện\\size[16] bởi",
    " \\p[4]\\size[15]  Ellen's past, meeting Viola, the" => "\\p[4]\\size[15]  Quá khứ của Ellen, cuộc gặp gỡ với Viola,",
    " \\px[380]  \\c[14]blonde\\c[0] or \\c[10]red hair\\c[0]." => "màu vàng\\c[0] hoặc \\c[10]màu đỏ\\c[0].",
    " \\px[600]- Dad" => "\\px[600]- Cha",
    " \\right- Dad" => "\\right- Bố",
    " \\size[18]" => "\\size[18]",
    " \\size[19] All \\size[22]mysteries\\size[19] are revealed.\\|\\hold\\^" => "\\size[19] Mọi \\size[22]bí ẩn\\size[19] đều được hé lộ.\\|\\hold\\^",
    " \\size[22]\\B E-book Edition\\.  \\>\\size[20]Free on \\B\\c[14]\\_" => "\\size[22]\\B Bản E-book\\.  \\>\\size[20]Miễn phí trên \\B\\c[14]\\_",
    " \\size[22]\\B\\size[26]\"The Witch's House: The Diary of Ellen\"" => "\\size[22]\\B\\size[26]\"Ngôi Nhà Phù Thủy: Nhật Ký Ellen\"",
    " \\size[22]\\B\\size[26]\"The Witch\\'s House: The Diary of Ellen\"" => "\\size[22]\\B\\size[26]\"Ngôi Nhà Phù Thủy: Nhật Ký Ellen\"",
    " \\size[30]\"\\s[2]You killed him.\"\\|\\^" => "\\size[30]\"\\s[2]Ngươi đã giết nó.\"\\|\\^",
