    "... always lying ... be careful ..." => ".... Kẻ lừa gạt ..... cẩn trọng .....",
    "... are their characteristics." => "... là đặc điểm của chúng.",
    "...Be silent.\"" => "....Nhưng ta cần cô hãy giữ im lặng.\"",
    "...Didn't you hear me before?\"" => "... Cô không nghe tôi nói gì trước đó à?",
    "...Don't have a...! \\!Without that...\"" => "...Không có thuốc...! \\!Không có nó thì...\"",
    "...Don't have a...! \\!Without that...\\\"" => "...Không có thuốc...! \\!Không có nó thì...\\\"",
    "...Don't have one...? \\!Without one...\"" => "...Mày không có nó sao...? \\!không có nó...\"",
    "...Feels like it's empty." => "Cảm giác như nó trống không.",
    "...Feels like the head moved." => "...Có cảm giác như đầu của nó vừa di chuyển.",
    "...Heehee. \\.I guess I did say that.\"" => "...Hihi. \\.Chắc tôi có nói thế thật.\"",
    "...Heehee. \\.I guess I did say that.\\\"" => "...Hihi. \\.Chắc tôi có nói thế thật.\\\"",
    "...Heehee. \\.Maybe I did promise that.\"" => "...Heehee. \\.Có lẽ tớ đã hứa như thế.\"",
    "...How many times must I tell you?\"" => "....Tôi phải gọi cô bao nhiêu lần nữa đây?\"",
    "...It didn't do anything." => "....Nó sẽ không làm gì đâu.",
    "...It's not locked." => "...Nó không bị khóa.",
    "...It's unlocked." => "....Nó đã mở.",
    "...Kidding!\"\\|\\.\\^" => "....Đùa thôi!\"\\|\\.\\^",
    "...Need my help?" => "...Cần tôi giúp không?",
    "...Someone's moaning inside.\\!" => "...Có tiếng ai đó đang rên rỉ bên trong.\\!",
    "...Something feebly flaps its wings." => "...Có gì đó đang vỗ cánh một cách yếu ớt.",
    "...That's the truth, okay?\"" => "...Đó là sự thật, được chưa?\"",
    "...The white and black keys go up and down" => "...Phím trắng và phím đen đang chuyển động lên xuống",
    "...There's nothing caught in it." => "....Và không có gì trên đó cả.",
    "...They're all beautiful and love to chat.\\!" => "...Tất cả chúng đều xinh đẹp và rất thích tán gẫu.\\!",
    "...You don't feel anything." => "...Bạn không cảm nhận được gì cả.",
    "...You don't sense anything inside." => "....Bạn không cảm nhận được thứ gì bên trong nữa.",
    "...You dropped the bowl." => "....Bạn đã làm rơi bát.",
    "...You feel like it changed places." => "...Bạn cảm thấy như nơi này đã thay đổi.",
    "...You feel like it wasn't there before." => "...Bạn cảm thấy dường như trước đó nó không ở đây.",
    "...You hear someone leaving the other cell.\\|" => "....Bạn nghe thấy tiếng ai đó rời đi từ phòng kế bên.",
    "...You think the head moved." => "...Bạn nghĩ rằng cái đầu vừa cử động.",
    "...You thought it moved slightly." => "....Bạn tưởng rằng nó vừa bị xê dịch một chút.",
    "...You'd rather I wasn't? Ah, well.\"" => "...Cô không muốn tôi sao? À ừ, cũng được thôi.\"",
    "...\\!Someone's there." => "...\\!Có ai đó ở đằng kia.",
    "...\\!The white and black keys go up and down" => "...\\!Phím trắng và phím đen đang chuyển động",
    "...\\!You see a white sheet in a crack on the wall.\\!" => "...\\!Bạn thấy một mảnh giấy trắng nhét trong kẽ tường.\\!",
    "...\\!You see a white sheet stuck in a crack in the wall.\\!" => "...\\!Bạn thấy một mảnh giấy trắng kẹt trong kẽ tường.\\!",
    "...\\.But these are so \\w[1]f\\w[1]i\\w[1]l\\w[1]t\\w[1]h\\w[1]y\\w[1].\"" => "...\\.Nhưng thứ này\\|\\c[2] thật\\.\\. bẩn\\.\\. thỉu\"",
    "...\\.Eyeballs." => "...\\.Nhãn cầu.",
    "...\\.I thought you were pretty fond of it.\"" => "....Tôi nghĩ cô khá thích nó.\"",
