    "...\\.There's some small text on the door." => "...\\.Có một dòng chữ nhỏ trên cửa.",
    "...\\.You disappeared from the mirror." => "...\\.Hình ảnh của bạn không hiện trên gương.",
    "...\\.You hear something big slithering." => "...\\.Bạn nghe thấy một thứ gì đó rất to lớn\nđang trườn tới.",
