    "Bear↑" => "Phòng Gấu (Trên)",
    "Bear↓" => "Phòng Gấu (Dưới)",
    "Beautiful Flower" => "\\>Bông hoa xinh đẹp\\<",
    "Because \"she\" showed up, it looks like.\"" => "Vì có vẻ như \"cô ta\" đã xuất hiện rồi.\"",
    "Begin" => "Bắt Đầu",
    "Being a powerless human hasn't been so bad." => "Với ta thì cơ thể người phàm cũng không đến nỗi tệ.",
    "Better not with the fire still burning." => "Tốt hơn là không có lửa vẫn cháy.",
    "Black Cat" => "Mèo Đen",
    "Black Cat\n\"And it seems the magic of the house\nhas gone back to her.\"\nBlack Cat\n\"Which means the magic's gonna go poof, right?\nIf I stay here, I might get gobbled up with it.\"" => "\\>Hắc Miêu\\<\n\"Và có vẻ như phép thuật trong căn nhà đang quay\nlại với con bé.\"\n\\>Hắc Miêu\\<\n\"Nghĩa là tất cả phép thuật ở đây sẽ biến mất hết,\nđúng không?\nNếu còn ở lại đây, tôi sẽ bị cuốn vào mất.\"",
    "Black Cat\n\"I kinda like this place.\\!\nYou?\"" => "\\>Hắc Miêu\\<\n\"Tôi khá thích nơi này, còn cô?\"",
    "Black Cat\n\"Might as well, if you can't leave.\"" => "\\>Hắc Miêu\\<\n\"Có lẽ không còn cách nào khác, nếu cô không\nthể ra khỏi đây\"",
    "Black Cat\n\"Yo.\"\nBlack Cat\n\"Yeah, I'm here too. All in the job.\"" => "\\>Hắc Miêu\\<\n\"Chào.\"\n\\>Hắc Miêu\\<\n\"Yeah, ta cũng ở đây mà.\nVì công việc thôi\"",
