    "Dear Viola," => "Viola thân yêu,",
    "Dear Viola,\nI'm sorry for yelling at you yesterday.\n\nThere's an old legend that says a witch lives in\n\\fs[27]the forest, and kidnaps children who get lost there.\\fs[29]\n\nYour friend's house is very near the forest,\nso... I was worried about you.\n\nYour friend's name was Ellen, right? Well," => "Gửi viola yêu dấu.\nCha xin lỗi vì đã lớn tiếng với con vào\nngày hôm qua.\nCó một truyền thuyết từng kể rằng có một phù\nthủy sống trong khu rừng, và chuyên bắt cóc\nnhững đứa trẻ nào bị lạc.\n\nNhà bạn con khá gần khu rừng,\nnên... Cha sợ con gặp phải chuyện gì xấu.\n\nTên bạn của con là Ellen, phải không?",
