    "Gấu Bông" => "Gấu Bông",
    "Hall" => "Đại Sảnh",
    "Hand over bear limbs" => "Trao chân tay gấu bông",
    "He's a kind man. \\!A hunter, isn't he?\"" => "Ông ấy là người tốt bụng. \\!Một người thợ săn, đúng chứ?\"",
    "Heard an unlocking sound somewhere.\\.\\." => "Nghe thấy tiếng mở khóa ở đâu đó.\\.\\.",
    "Heard the lid of a glass case coming off." => "Nghe thấy tiếng nắp hộp kính mở ra.",
    "Her gaze goes far into the distance." => "Ánh mắt của cô ấy nhìn xa xăm.",
    "Her only wish was that" => "Khát vọng duy nhất của cô ấy là",
    "Here are their characteristics." => "Đó là đặc điểm để nhận dạng chúng.",
    "His cart had broken down in the woods," => "Xe của ông bị hỏng trong rừng,",
    "His country had perished, and he had died," => "Đất nước đã sụp đổ, và anh cũng đã tử trận,",
    "His head is bent." => "Và đầu của nó đã bị hỏng.",
    "His legs are bent." => "Và chân của nó đã bị hỏng.",
    "Hit" => "Gõ",
    "Hit bowl with key" => "Gõ chìa khóa vào bát.",
    "Hoa Hồng" => "Hoa Hồng",
    "Hope to see you home soon." => "Cha mong con sẽ về nhà sớm.",
    "House" => "Ngôi Nhà",
    "Hộp Sọ" => "Hộp Sọ",
    "Hộp chú hề." => "Một hộp hề.",
    "I can hear it making that unbearable racket.\"" => "mà ta vẫn nghe thấy tiếng ồn đó.\"",
    "I can't find it...\"" => "nó đâu rồi....\"",
    "I could almost forget about putting on an act." => "tôi gần như đã quên đi vai diễn của mình.",
    "I couldn't even move from my bed.\"" => "Tao thậm chí còn chẳng nhấc nổi mình khỏi giường.\"",
    "I do" => "Tôi có",
    "I don't" => "Tôi không có",
    "I don't feel any pain in this body.\"" => "Tao chẳng cảm thấy đau đớn gì trong cơ thể này cả.\"",
    "I don't hear that racket anymore.\"" => "ta không còn nghe ồn ào nữa rồi.\"",
    "I don't mind if you go out to play," => "Cha không phiền nếu con ra ngoài chơi",
    "I don't mind if you go out to play, but just stay" => "Bố không cấm con ra ngoài chơi, nhưng hãy ở",
    "I don't need that kinda junk.\"" => "Tôi không cần mấy thứ rác rưởi đâu.\"",
    "I dont" => "Tôi không có",
    "I don’t" => "Tôi không có",
    "I guess you don't know a thing, eh?\"" => "Tôi đoán là có một điều mà cô vẫn chưa biết nhỉ?\"",
    "I hate my illness." => "Tôi ghét căn bệnh của tôi.",
    "I have to applaud your tenacity.\"" => "Tớ rất khâm phục sự kiên trì của cậu đấy.\"",
    "I love flowers." => "Tôi rất thích hoa.",
    "I quite like a black cat's body.\"" => "Tôi khá thích cơ thể mèo đen này đấy.\"",
    "I quite like a black cat\\'s body.\"" => "Tôi khá thích cơ thể mèo đen này đấy.\"",
    "I reached out." => "Tôi đưa tay ra.",
    "I wanted to snap your thin neck." => "tôi chỉ muốn bẻ gãy cổ của cô.",
    "I was in need of a hand, or two.\"" => "Tôi đang cần một hoặc hai bàn tay.\"",
    "I was sick,\nso no one played with me.\n\nMy father and my mother\ndidn't love me." => "\nTôi bị bệnh,\nNên không ai tới chơi với tôi cả.\n\nCha và mẹ tôi không yêu thương tôi.",
    "I wouldn't X her.\nBecause she would save me\nfrom my sickness.\n\nSo I made her my \"friend.\"" => "\nTôi không X cô ấy.\nBởi vì cô ấy có thể giúp tôi thoát khỏi căn bệnh này.\n\nNên tôi đã biến cô ấy trở thành \"bạn\" của tôi.",
    "I'd been searching the whole forest.\"" => "Tôi đã tìm kiếm khắp cả khu rừng.\"",
    "I'll give him \\.\\s[4]Viola's share of love.\"" => "Tôi sẽ trao cho ông ấy \\.\\s[4]phần tình thương của Viola.\"",
    "I'll head right back.\"" => "Tôi sẽ quay về ngay.\"",
    "I'll make sure his daughter, Viola, gives him" => "Tao sẽ đảm bảo con gái ông ấy, Viola, trao cho ông",
    "I'm fine, thanks" => "Tôi khỏe, cảm ơn",
    "I'm going to die from my sickness.\\." => "Mình chắc chắn sẽ chết bởi căn bệnh này.\\.",
    "I'm kinda disappointed.\"" => "Cô làm tôi buồn đấy.\"",
    "I'm sorry for yelling at you yesterday." => "Bố xin lỗi vì đã mắng con hôm qua.",
    "I've been in this house ever since." => "Tôi đã sống trong ngôi nhà này kể từ khi đó.",
    "I\\'d been searching the whole forest.\"" => "Tôi đã lùng sục khắp cả khu rừng.\"",
    "I\\'ll give him \\.\\s[4]Viola\\'s share of love.\"" => "Tôi sẽ trao cho ông ấy \\.\\s[4]phần tình thương của Viola.\"",
    "If I stay here, I'm gonna vanish with it.\"" => "Nếu còn ở lại đây, tôi cũng sẽ tan biến cùng nó.\"",
    "If I stay here, I\\'m gonna vanish with it.\"" => "Nếu còn ở lại đây, tôi cũng sẽ tan biến cùng nó.\"",
    "If he wouldn't look at her, she didn't need him." => "để ý đến XXX, thì XXX không cần ông ta nữa.",
    "If she wouldn't love her, she didn't need her." => "còn yêu XXX, thì XXX không cần bà ta nữa.",
    "If you cut any more, there'd be no bear left." => "Nếu bạn cắt tiếp nữa thì không còn con gấu\nnào nữa đâu.",
    "Im fine, thanks" => "Tôi khỏe, cảm ơn",
    "In addition, silver utensils change color upon" => "Ngoài ra, đồ dùng bằng bạc sẽ đổi màu khi",
    "In return, demons give witches magic." => "Đổi lại, Ác quỷ sẽ ban cho Phù thủy phép thuật.",
    "Insect models are lined up" => "Những mô hình côn trùng được xếp gọn",
