    "Long ago, in a poor town,\nthere lived a sick girl named XXX.\n\nFrom birth, XXX's face and legs festered,\nso she kept them wrapped in bandages.\n\nXXX's father never looked at her,\nnor did he ever speak to her.\n\nEven so, XXX was happy.\nBecause at least XXX's mother loved her." => "\nRất lâu trước kia, tại một thị trấn nghèo,\ntừng tồn tại một cô bé bệnh tật mang tên XXX.\n\nTừ khi XXX được sinh ra, mặt và chân của\ncô bị mưng mủ, vì thế nên cô luôn phải\n\nquấn chúng lại bằng băng cứu thương.\n\nCha XXX chưa bao giờ để mắt tới cô ấy,\ncũng như nói chuyện với cô ấy.\n\nDù thế nhưng XXX vẫn hạnh phúc.\nVì ít nhất mẹ của XXX vẫn yêu thương cô ấy.",
