    "People of ruling and wealthy classes" => "Tầng lớp cai trị và giới quý tộc",
    "People of ruling and wealthy classes\nhave long enjoyed dining with silverware.\nUsing such hard-to-clean cutlery proved\nthey were wealthy enough to hire servants.\nIn addition, silver utensils change color upon\ncontact with poison, making them quite useful." => "Từ lâu, giới tộc và những người thuộc tầng lớp\ngiàu có đã có sở thích sử dụng dao nĩa thìa bằng\nbạc.\nChúng khá khó để rửa sạch vết bẩn\nnhưng họ đủ giàu để thuê vài người\nhầu lao rửa chúng sạch sẽ.\nNgoài ra, bạc có thể đổi màu khi tiếp xúc với\nchất độc, đó cũng là một trong những lý do\nkhiến nó được giới quý tộc ưa chuộng.",
