    "X" => "X",
    "X her with your great big arms.\"" => "bạn X cô ta bằng cánh tay đó.\"",
    "XX and his wife XX were found" => "XX và vợ của XX đã được tìm thấy",
    "XX/XX: XX Residence Burns Down" => "Ngày XX tháng XX: nhà của XX đã bị cháy.",
    "XXX X-ed her father." => "XXX đã X cha của cô ấy. Nếu ông ta không còn",
    "XXX X-ed her mother." => "XXX đã X mẹ của cô ấy. Nếu bà ta không",
    "XXX could not die, for she was not human." => "XXX không thể chết, vì cô ấy không còn là người.",
    "XXX did not die, for she never despaired." => "XXX chưa chết, vì cô ấy chưa từng tuyệt vọng.",
    "XXX made him a request.\n\"I want a human friend.\"\n\nIn his black cat form, \"he\" assented.\nHowever...\n\nXXX didn't see it.\n\nShe didn't see the \\c[10]hideously evil\nsmile that crept up on \"his\" face.\\c[0]" => "\nXXX đã đưa hắn ta một yêu cầu.\n\"Tôi muốn có một người bạn là loài người.\"\n\n\"Hắn ta\", bên dưới hình dạng của con mèo đen,\nđã chấp nhận yêu cầu.\n\nTuy nhiên...\n\nXXX không hề nhìn thấy.\n\nCô không hề nhìn thấy \\c[10]nụ cười đầy hiểm ác\nđang hiện trên mặt của \"hắn ta\".\\c[0]",
    "XXX ran away from home." => "XXX chạy khỏi căn nhà đó. Và rồi cô gặp",
    "XXX was no longer a sick girl." => "XXX không còn là một cô bé bị bệnh tật nữa.",
    "Yellow Flower" => "Bông hoa vàng",
    "Yellow Flower\n\"Hm? Ah yes, our promise. Here you are.\"" => "Bông hoa vàng\n\"Hm? À phải rồi, về thỏa thuận của chúng ta.\nĐây, của cô đây.\"",
    "Yellow Flower\n\"I heard it! I heard her ugly wail!\"\n\"I heard it!\"　　　　　　　\\^\n\n\"I heard it!\"　　　　　　　\\^\n\n\n\"I heard it!\"　　　　　　　\\^" => "\\>Bông hoa vàng\\<\n\"Ta nghe thấy nó! Ta nghe thấy tiếng kêu la của\ncon mụ xấu xí đó rồi!\"\n\n\"Ta nghe thấy rồi!\"　　　　　　\\^\n\n\"Ta nghe thấy rồi!\"　　　　　　\\^\n\n\"NGHE THẤY RỒI!!!\"　　　　　　\\^",
    "Yellow Flowers (All)" => "\\>Bông hoa vàng (Tất cả)\\<",
    "Yellow flowers" => "Bông hoa vàng",
    "Yes" => "Có",
    "You came to play with me." => "Cậu đến chơi với tớ à.",
    "You can pass through now." => "Bây giờ bạn có thể băng qua nó.",
    "You can see inside a small tear in it.\\!" => "Bạn có thể nhìn thấy bên trong vết rách nhỏ.\\!",
    "You can see some sort of lever." => "Bạn có thể nhìn thấy một chiếc cần gạt.",
    "You can't even tell what it is, exactly." => "Bạn thậm chí không biết chính xác nó là gì.",
    "You can't even tell what it is." => "phân biệt được có thứ gì trong đó.",
    "You can't open the door holding a doll." => "Bạn không thể mở cửa khi đang vác con búp bê.",
    "You can't reach the clock." => "Bạn không thể chạm tới cái đồng hồ.",
    "You can't read it from behind." => "Bạn không thể đọc nó từ phía sau.",
    "You can't read it from the side." => "Không thể đọc nó từ phía bên cạnh.",
    "You can't read it while carrying the doll." => "Bạn không thể đọc nó khi đang vác búp bê.",
    "You can't read them from here." => "Không thể đọc chúng từ đây.",
    "You can't see anywhere to use the key." => "Bạn không nhìn thấy chỗ nào để sử dụng chìa khóa.",
    "You cut off the teddy bear's limbs." => "Bạn đã cắt bỏ tay chân gấu bông.",
    "You don't want to smell it any longer." => "Bạn không muốn ngửi nó thêm một lần nào nữa.",
    "You dropped the bottle." => "Bạn đã làm rớt lọ thủy tinh.",
    "You felt like it opened its eyes to look at you." => "Bạn cảm thấy như nó đã mở mắt nhìn bạn.",
    "You hear a pleasant sound." => "Bạn nghe thấy một âm thanh rất êm dịu.",
    "You hear nothing." => "Bạn không nghe thấy gì trong đó cả.",
    "You heard something unlock.\\.\\." => "Bạn nghe cái gì đó được mở khóa.",
    "You heard water running." => "Bạn nghe thấy tiếng nước chảy.",
    "You know that body won't last long.\"" => "Cô biết cơ thể đó sẽ chẳng tồn tại được lâu đâu.\"",
    "You know that body won\\'t last long.\"" => "Cô biết cơ thể đó chẳng trụ được lâu mà.\"",
    "You know you're almost dead.\\fs[29]\"" => "Mày biết mày sắp chết đến nơi rồi mà.\\fs[29]\"",
    "You looking for something?\"" => "Cô đang tìm gì à?\"",
    "You nearly got pecked." => "Suýt nữa bạn đã bị nó mổ trúng.",
    "You put the book on the shelf." => "Bạn đã đặt cuốn sách lên kệ.",
    "You see a bloody reflection." => "Bạn thấy một hình bóng đẫm máu phản chiếu.",
    "You see nothing." => "Bạn không thấy gì trong đó cả.",
    "You see yourself covered in blood." => "Bạn thấy người mình dính đầy máu.",
    "You sense there's someone sitting here." => "Bạn cảm nhận có ai đó đang ngồi đây.",
    "You should just give up on it.\"" => "Cô nên sớm từ bỏ nó đi.\"",
    "You washed off the blood to reveal" => "Phần máu đã bị rửa trôi để lộ ra một đôi giày",
    "You were spit at." => "Bạn bị nhổ nước bọt vào người.",
    "You wouldn't dare do that with your bare hands." => "Bạn không dám chạm vào nó bằng tay không.",
    "Your friend's house is very near the forest," => "Nhà bạn con rất gần khu rừng,",
    "Your friend's name was Ellen, right? I don't" => "Tên bạn con là Ellen, đúng không? Bố không",
    "Your friend's name was Ellen, right? Well," => "Tên bạn con là Ellen, đúng không? Chà,",
    "Your hands are busy holding the doll." => "Hai tay bạn đang bận ôm búp bê.",
    "Your vision is getting too blurry." => "Tầm nhìn của bạn đang mờ dần.",
    "\\!...Gotcha.\"" => "\\!.....Ta bắt được mi rồi!\"",
    "\\!...Well, I was here before.\"" => "Mà chắc là ta ở đây từ trước thôi.\"",
    "\\!...You knew that? Right, right." => "\\!...Cô biết rồi à? Đúng vậy, đúng vậy.",
    "\\!...You knew that? Right, right. Well...\"" => "\\!...Cô đã biết rồi phải không?\\. Chắc chắn rồi...\"",
    "\\!...You knew that? Right, right.\"" => "\\!...Cô biết điều đó rồi à? Đúng vậy, phải rồi.\"",
    "\\!...\\|...\\|...\"" => " \\!...\\|...\\|...\"",
    "\\!Incidentally, where the heck'd you come out from?\"" => "\\!Nhân tiện, rốt cuộc cô chui từ chỗ quái nào ra vậy?\"",
    "\\!Incidentally, where the heck'd you come out from?\\fs[29]\"" => "\\!Mà cô chui từ chỗ quái nào ra vậy?\\fs[29]\"",
    "\\!It'd quickly snap under your weight." => "\\!Nó sẽ lập tức sập xuống dưới trọng lượng của bạn.",
    "\\!It'd snap any second under your weight." => "\\!Nó có thể gãy bất cứ lúc nào dưới sức nặng của bạn.",
    "\\!That ain't nice.\"" => "Điều này méo vui đâu!\"",
    "\\!The key turned black in the soup." => "\\!Chìa khóa đang dần chuyển sang màu đen.\"",
    "\\!The lever has been pulled." => "\\!Cần gạt đã được gạt.",
    "\\!Viola was poisoned." => "\\!Viola đã bị dính độc.",
    "\\!We'd share some of our wonderful pollen.\"" => "Chúng ta sẽ thưởng cho người đó một ít phấn hoa.\"",
    "\\.Because we're \"friends.\"" => "\\.Bởi vì chúng ta là \"bạn\".",
    "\\.I'm going to live on in her body." => "\\.Mình sẽ sống bên trong cơ thể của cô ấy.",
    "\\.Suddenly, something screamed." => "\\.Đột nhiên, có thứ gì đó hét lên.",
    "\\.You can see some sort of lever." => "\\.Bạn có thể thấy cái gì đó như một cái cần gạt.",
    "\\.\\....because we're \"friends.\"" => "\\.\\.... Bởi vì chúng ta là \"bạn.\"",
    "\\.\\.I know she'll say yes.\n\n\nBecause \\.she's so kind.\n\nBecause \\.she's so trusting.\nViola's going to be so surprised\\.\\.\nwhen we trade bodies.\n\\.My body's \\.\\.falling apart.\\.\\.\nIt hurts all over.\n\\.\\.I've gotten used to it,\\.\\.\nbut she probably can't take it.\n\n\\.It might make her cry and scream.\n\n\\.\\.\\.So I'll give her medicine.\n\\.\\.M\\w[1]e\\w[1]d\\w[1]i\\w[1]c\\w[1]i\\w[1]n\\w[1]e\\w[1] \\w[1]t\\w[1]h\\w[1]a\\w[1]t\\w[1] \\w[1]w\\w[1]i\\w[1]l\\w[1]l\\w[1] \\w[1]b\\w[1]u\\w[1]r\\w[1]n \\w[1]h\\w[1]e\\w[1]r\\w[1] \\w[1]t\\w[1]h\\w[1]r\\w[1]o\\w[1]a\\w[1]t\\.\\.\nto make sure she stays quiet.\n\\.\\.After all, I don't want to hear\nmy own screaming.\n\\.\\.I know she'll drink it if I lie and say\\.\\.\nit'll stop the pain. \\.\\.\\.Heehee.\n\n\\.\\.\\.Then I'll escape from this room.\n\\.\\.I'll be able to feel a gentle breeze wash\nover me in the garden.\\! It'll be so wonderful.\n\n\\.\\.Ah, that's right.\n\\.\\.Before she gets here,\\.\\.\nI should gouge my eyes out.\\.\\.\n\nI'll cut off my legs, too.\\.\\.\n\\.\\.That way, Viola will be so overcome\nwith despair\\.\\. that she'll have to die.\n\n\\.\\.Ahhh... \\.\\.Viola.\n\n\\.My dear \"friend.\"\n\\.\\.So kind, \\.so charming, \\.so loved.\\.\\.\\.\nAnd with all that, \\.so foolish.\n\n\\.My dear \"friend.\"" => "\n\\.\\.Mình biết cô ấy sẽ nói đồng ý.\n\nBởi vì \\.cô ấy rất tốt bụng.\n\nVà \\.rất đáng tin cậy.\n\nViola đã rất ngạc nhiên\\.\\.\nkhi chúng tôi trao đổi thân xác với nhau.\n\n\\.Cơ thể của tôi \\.\\.như bị xé nát.\\.\\.\nCảm giác đau đớn không thể tả.\n\n\\.\\.Tôi đã quen với nó,\\.\\.\nnhưng cô ấy chắc chắn sẽ không chịu nổi nó.\n\n\\.Nó có thể làm cô ấy khóc và hét toáng lên.\n\n\\.\\.\\.Nên tôi đã đưa cho cô ấy thuốc của mình,\n\n\\.\\.\\c[2]Thuốc mà sẽ làm cổ họng bị thiêu\nhủy khi uống vào\\.\\.\n\n\\c[2]để chắc chắn rằng cô ấy sẽ\nluôn giữ yên lặng.\n\n\\.\\.Dù gì thì, mình cũng không muốn nghe thấy\ntiếng của mình khi hét toáng lên thế kia.\n\n\\.\\.\\c[2]Mình cam đoan cô ấy sẽ uống nó\nkhi mình nói dối rằng\\.\\.\n\n\\c[2]thứ thuốc đó sẽ chấm dứt cơn đau.\n\\.\\.\\.Heehee....\n\n\\.\\.\\.Và mình sẽ có thể cảm nhận được\ncơn gió lạnh luồng qua mình ở khu vườn.\\!\n\nNó chắc chắn sẽ rất tuyệt.\n\n\\.\\.\\.Ah, phải rồi.\n\n\\.\\.Trước khi cô ấy đến đây,\\.\\.\nMình phải nên móc đôi mắt này ra.\\.\\.\n\nMình cũng sẽ cắt đi đôi chân này.\\.\\.\n\n\\.\\.Bằng cách này, Viola sẽ trở nên tuyệt vọng\\.\\.\nvà cô ấy sẽ chết.\n\n\\.\\.Ahhh... \\.\\.Viola.\n\n\\.\"Người bạn\" yêu quý của tôi.\n\n\\.\\.Thật tốt, \\.thật quyến rũ, \\.thật đáng yêu.\\.\\.\\.\nVà sau tất cả,\\. cô thật ngu ngốc.\n\n\\.\"Người bạn\" yêu quý của tôi.",
    "\\.\\.I'm going to take her body." => "\\.\\.Mình sẽ chiếm lấy cơ thể của cô ấy.",
    "\\.\\.So...\\." => "\\.\\.Nên...\\.",
    "\\.\\.That's why y\\w[2]o\\w[2]u\\w[2] \\w[2]c\\w[2]a\\w[2]m\\w[2]e\\w[2] \\w[2]t\\w[2]o\\w[2] \\w[2]p\\w[2]l\\w[2]a\\w[2]y\\w[2] \\w[2]w\\w[2]i\\w[2]t\\w[2]h\\w[2] \\w[2]m\\w[2]e\\w[2] \\w[2]t\\w[2]o\\w[2]d\\w[2]a\\w[2]y\\w[2]..." => "\\.\\.Đó là lí do vì sao cậu đến chơi với mình hôm nay...",
