    "\\|...\\|The piano begins playing itself." => "\\|...\\|Đàn piano bắt đầu tự chơi.",
    "\\|It won't open." => "\\|Nó không chịu mở.",
    "\\|You hear someone coming down the stairs\\|... \\|... \\|...\\|" => "\\|Bạn nghe thấy tiếng ai đó đi xuống cầu thang\\|..\\|...\\|...\\|",
    "\\|\\s[2]You hear someone coming down the stairs\\|... \\|... \\|...\\|" => "\\|\\s[2]Bạn nghe thấy tiếng ai đó đang bước xuống cầu thang\\|... \\|... \\|...\\|",
    "\\|\\|\\|\\|\\|\\B\\size[16]" => "\\|\\|\\|\\|\\|\\B\\size[16]",
    "a silver coin, to carry in his mouth." => "một đồng bạc để ngậm trong miệng.",
    "a spell to cure her sickness." => "một câu thần chú để chữa lành bệnh tật.",
    "a strong medicine that can kill or give life." => "là một loại độc dược vừa cứu mạng vừa đoạt mạng.",
    "a transparent pair of shoes.\\.\\." => "thủy tinh trong suốt.",
    "and \\c[20]brown-eyed\\c[0]" => "và \\c[20]mắt nâu\\c[0]",
    "and \\c[20]brown-eyed\\c[0] women can have either" => "và người có có đôi mắt \\c[20]màu nâu\\c[0] sẽ có thể có tóc \\c[14]",
    "and a 13 card with a king on it." => "và 13 thẻ bài với ông vua trên đó.",
