    "of your own accord, y\\'know?\"" => "theo ý muốn của mình đâu, biết không?\"",
    "or if the house eats you alive.\"" => "hay bị ngôi nhà này ăn sống.\"",
    "physical forms doesn't make us immortal.\"" => "thể xác đâu có nghĩa là chúng tôi bất tử.\"",
    "physical forms doesn\\'t make us immortal.\"" => "xác thịt đâu có nghĩa là chúng tôi bất tử.\"",
    "playing with some yarn." => "đùa giỡn với cuộn len tròn.",
    "promise that, and maybe not.\"" => "Có lẽ tôi đã hứa điều đó, và cũng có lẽ không.\"",
